import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { CustomTextDefs } from '../../interfaces/customtext.interfaces';
import { customTextDefaults } from '../../objects/customTextDefaults';

@Injectable({
  providedIn: 'root'
})
export class CustomtextService {
  private customTexts: { [key: string]: BehaviorSubject<string | null> } = {};

  addCustomTexts(newTexts: { [key: string]: string }): void {
    Object.keys(newTexts).forEach(key => {
      this.addCustomText(key, newTexts[key]);
    });
  }

  addCustomTextsFromDefs(newTexts: CustomTextDefs): void {
    Object.keys(newTexts).forEach(key => {
      this.addCustomText(key, newTexts[key].defaultvalue);
    });
  }

  private addCustomText(key: string, value: string): void {
    if (typeof this.customTexts[key] === 'undefined') {
      this.customTexts[key] = new BehaviorSubject<string | null>(null);
    }
    this.customTexts[key].next(value);
  }

  getCustomText$(key: string): BehaviorSubject<string | null> {
    if (typeof this.customTexts[key] === 'undefined') {
      this.customTexts[key] = new BehaviorSubject<string | null>(null);
    }
    return this.customTexts[key];
  }

  restoreDefault(all: boolean): void {
    if (typeof this.customTexts === 'undefined') {
      return;
    }

    Object.keys(this.customTexts).forEach(k => {
      if (this.customTexts[k] && customTextDefaults[k]) {
        this.customTexts[k].next(customTextDefaults[k].defaultvalue);
      }
      if (all) {
        if (!(k in customTextDefaults) && this.customTexts[k]) {
          this.customTexts[k] = new BehaviorSubject<string | null>(null);
        }
      }
    });
  }

  getCustomText(key: string): string {
    if (typeof this.customTexts[key] === 'undefined') {
      return '';
    }
    return this.customTexts[key].getValue() ?? '';
  }

  getCustomTextKeys(): Array<string> {
    return Object.keys(this.customTexts);
  }
}

import { Pipe, PipeTransform } from '@angular/core';
import { Observable, of } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { CustomtextService } from '../../services/customtext/customtext.service';
import { environment } from '../../../../environments/environment';

/** Output depends on the environment.ts. If the given default value is an empty string: *) In Production, the function
 * returns an empty string; *) In Dev the function returns the key argument, for debugging purposes. */
@Pipe({
  name: 'customtext'
})
export class CustomtextPipe implements PipeTransform {
  constructor(private cts: CustomtextService) {}

  transform(defaultValue: string, key: string, ...replacements: Array<string | number>): Observable<string> {
    return of('...')
      .pipe(
        switchMap(() => this.cts.getCustomText$(key)),
        map(customText => {
          if (customText) {
            return customText;
          }
          // TODO change direct call of environment with Inject Token 'IS_PRODUCTION_MODE', somehow didn't work
          return environment.production ? defaultValue : (defaultValue || key);
        }),
        map(customText => {
          replacements
            .map(replacement => (typeof replacement === 'number' ? String(replacement) : replacement))
            .forEach(replacement => {
              // eslint-disable-next-line no-param-reassign
              customText = customText
                .replace('%s', replacement)
                .replace('%date', new Date(replacement).toLocaleString());
            });
          return customText;
        })
      );
  }
}

import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { CustomtextService } from '../services/customtext/customtext.service';
import { KeyValuePairs } from '../../app.interfaces';
import {
  AppSettings,
  SysConfig,
  XmlSchemaVersions
} from '../interfaces/app-config.interfaces';
// eslint-disable-next-line import/no-relative-packages
import customTextsDefaultJSON from '../../../../../definitions/testtaker/custom-texts.json';

const customTextsDefault = customTextsDefaultJSON as {
  [k: string]: {
    'label': string,
    'defaultvalue': string
  }
};

export class AppConfig {
  sanitizer: DomSanitizer;
  cts: CustomtextService;
  defaultThemeName: string;
  customTexts: KeyValuePairs = {};
  version = '';
  veronaPlayerApiVersionMin: number = 0;
  veronaPlayerApiVersionMax: number = 0;
  iqbStandardResponseTypeMin: number = 0;
  iqbStandardResponseTypeMax: number = 0;
  xmlSchemaVersions: XmlSchemaVersions = {};
  appTitle = 'IQB-Testcenter';
  privacyNotice = '';
  trustedPrivacyNotice: SafeUrl | null = null;
  accessibilityNotice = '';
  trustedAccessibilityNotice: SafeUrl | null = null;
  legalNoticeHtml = '';
  trustedLegalNoticeHtml: SafeUrl | null = null;
  globalWarningText = '';
  globalWarningExpiredDay = '';
  globalWarningExpiredHour = '';
  bruteForceProtection: string[] = [];
  broadcastingServiceUri: string = '';
  fileServiceUri: string = '';
  themeName: string = '';
  passwordMinLength: number = 0;
  passwordPattern: string = '';

  constructor(sysConfig: SysConfig, cts: CustomtextService, defaultThemeName: string, sanitizer: DomSanitizer) {
    this.sanitizer = sanitizer;
    this.cts = cts;
    this.defaultThemeName = defaultThemeName;
    this.setCustomTexts(sysConfig.customTexts);
    this.setAppConfig(sysConfig.appConfig);
    this.customTexts = sysConfig.customTexts;
    this.version = sysConfig.version;
    this.veronaPlayerApiVersionMin = sysConfig.veronaPlayerApiVersionMin;
    this.veronaPlayerApiVersionMax = sysConfig.veronaPlayerApiVersionMax;
    this.iqbStandardResponseTypeMin = sysConfig.iqbStandardResponseTypeMin;
    this.iqbStandardResponseTypeMax = sysConfig.iqbStandardResponseTypeMax;
    this.xmlSchemaVersions = sysConfig.xmlSchemaVersions;
    this.bruteForceProtection = sysConfig.bruteForceProtection;
    this.broadcastingServiceUri = sysConfig.broadcastingServiceUri;
    this.fileServiceUri = sysConfig.fileServiceUri;
    this.passwordMinLength = sysConfig.passwordMinLength;
    this.passwordPattern = sysConfig.passwordPattern;
  }

  setCustomTexts(customTexts: KeyValuePairs): void {
    const ctSettings: { [k: string]: string } = {};
    Object.keys(customTextsDefault).forEach(k => {
      ctSettings[k] = customTextsDefault[k].defaultvalue;
    });
    if (customTexts) {
      Object.keys(customTexts).forEach(k => {
        ctSettings[k] = customTexts[k];
      });
    }
    this.cts.addCustomTexts(ctSettings);
  }

  setAppConfig(appConfig?: AppSettings): void {
    this.appTitle = 'IQB-Testcenter';
    this.privacyNotice = 'privacyNotice text nicht definiert';
    this.trustedPrivacyNotice = null;
    this.accessibilityNotice = 'accessibilityNotice text nicht definiert';
    this.trustedAccessibilityNotice = null;
    this.legalNoticeHtml = '<p>Anbieter:<br>Max Mustermann<br>Musterstraße 1<br>13088 Berlin<br>' +
      '<br>Kontakt:<br>Telefon: 030/1234567-8<br>Telefax: 030/1234567-9<br>E-Mail: mail@mustermann.de' +
      '<br>Website: www.mustermann.de</p>';
    this.trustedLegalNoticeHtml = null;
    this.globalWarningText = '';
    this.globalWarningExpiredDay = '';
    this.globalWarningExpiredHour = '';
    this.themeName = this.defaultThemeName;
    if (appConfig) {
      if (appConfig.appTitle) this.appTitle = appConfig.appTitle;
      if (appConfig.legalNoticeHtml) this.legalNoticeHtml = appConfig.legalNoticeHtml;
      if (appConfig.privacyNotice) this.privacyNotice = appConfig.privacyNotice;
      if (appConfig.accessibilityNotice) this.accessibilityNotice = appConfig.accessibilityNotice;
      if (appConfig.globalWarningText) this.globalWarningText = appConfig.globalWarningText;
      if (appConfig.globalWarningExpiredDay) this.globalWarningExpiredDay = appConfig.globalWarningExpiredDay;
      if (appConfig.globalWarningExpiredHour) {
        this.globalWarningExpiredHour = appConfig.globalWarningExpiredHour;
      }
      if (appConfig.themeName) this.themeName = appConfig.themeName;
    }
    this.trustedLegalNoticeHtml = this.sanitizer?.bypassSecurityTrustHtml(this.legalNoticeHtml) ?? '';
    this.trustedPrivacyNotice = this.sanitizer?.bypassSecurityTrustHtml(this.privacyNotice) ?? '';
    this.trustedAccessibilityNotice = this.sanitizer?.bypassSecurityTrustHtml(this.accessibilityNotice) ?? '';
  }

  getWarningMessage(): string {
    if (this.globalWarningExpiredDay) {
      return AppConfig.isWarningExpired(this.globalWarningExpiredDay, this.globalWarningExpiredHour) ?
        '' : this.globalWarningText;
    }
    return this.globalWarningText;
  }

  static isWarningExpired(warningDay: string, warningHour: string): boolean {
    const targetDate = new Date(warningDay);
    targetDate.setHours(Number(warningHour));
    return targetDate < new Date(Date.now());
  }

  getAppConfig(): AppSettings {
    return {
      appTitle: this.appTitle,
      legalNoticeHtml: this.legalNoticeHtml,
      privacyNotice: this.privacyNotice,
      accessibilityNotice: this.accessibilityNotice,
      globalWarningText: this.globalWarningText,
      globalWarningExpiredDay: this.globalWarningExpiredDay,
      globalWarningExpiredHour: this.globalWarningExpiredHour,
      themeName: this.themeName
    };
  }
}

import {
  bufferWhen, concatMap, last, map, scan, shareReplay, takeUntil, takeWhile, tap, withLatestFrom
} from 'rxjs/operators';
import {
  BehaviorSubject, combineLatest, firstValueFrom, forkJoin, from,
  lastValueFrom, merge, Observable, of, Subject,
  Subscription, timer
} from 'rxjs';
import { Injectable } from '@angular/core';
import { PRIMARY_OUTLET, Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { CodingSchemeFactory } from '@iqb/responses';
import { TimerData } from '../classes/test-controller.classes';
import {
  Booklet,
  BufferFlushEvent,
  BufferFlushEventType,
  bufferTypes,
  isTestlet,
  isUnit,
  KeyValuePairNumber,
  KeyValuePairString,
  LoadingProgress,
  MaxTimerEvent,
  NavigationDirection, NavigationDirectionValue,
  NavigationLeaveRestrictionValue,
  NavigationState,
  StateReportEntry,
  TestControllerState,
  Testlet,
  TestletLockType,
  TestletLockTypes,
  TestStateKey,
  TestStateUpdate,
  Unit,
  UnitDataParts,
  UnitNavigationTarget, UnitStateKey,
  UnitStateUpdate,
  WindowFocusState
} from '../interfaces/test-controller.interfaces';
import { BackendService } from './backend.service';
import {
  BookletConfig,
  CustomtextService,
  MainDataService,
  TestMode
} from '../../shared/shared.module';
import {
  isVeronaProgress, SharedParameter,
  VeronaNavigationDeniedReason,
  VeronaProgressIncompleteValues
} from '../interfaces/verona.interfaces';
import { MissingBookletError } from '../classes/missing-booklet-error.class';
import { MessageService } from '../../shared/services/message.service';
import { AppError } from '../../app.interfaces';
import { isIQBVariable } from '../interfaces/iqb.interfaces';
import { TestStateUtil } from '../util/test-state.util';
import { ConditionUtil } from '../util/condition.util';
import { createTicker } from '../util/worker.util';

type LeaveCheckResult =
  // proceed; `notify` is an optional non-blocking FYI toast (test-mode preview of what would have
  // been blocked/warned about in real test mode)
  | { kind: 'allow'; notify?: string }
  // block navigation; either silently, with an FYI toast, or after a blocking info dialog the
  // user just acknowledges (no real choice involved)
  | { kind: 'deny'; notify?: string; infoDialog?: { title: string; content: string } }
  // block unless the user explicitly confirms leaving
  | { kind: 'confirm'; title: string; content: string; onConfirmed: () => string | undefined };

@Injectable({
  providedIn: 'root'
})
export class TestControllerService {
  testId = '';
  readonly state$ = new BehaviorSubject<TestControllerState>('INIT');
  workspaceId = 0;
  totalLoadingProgress = 0;
  readonly unitContentReady$ = new BehaviorSubject<boolean>(false);
  testMode = new TestMode();

  // TODO hide those behind functions, this will be way easier with ts 5.5
  booklet: Booklet | null = null;
  units: { [sequenceId: number]: Unit } = {};
  testlets: { [testletId: string] : Testlet } = {};
  unitAliasMap: { [unitId: string] : number } = {};

  private _currentUnitSequenceId = -Infinity;
  readonly currentUnitSequenceId$ = new BehaviorSubject<number>(-Infinity);
  configChanged$ = new Subject<void>(); // merely tracked that something changed, not interested in value
  get currentUnitSequenceId(): number {
    return this._currentUnitSequenceId;
  }

  set currentUnitSequenceId(value: number) {
    this._currentUnitSequenceId = value;
    this.currentUnitSequenceId$.next(value);
  }

  get currentUnit(): Unit | null {
    return this.units[this.currentUnitSequenceId];
  }

  timers$ = new Subject<TimerData>();
  timers: KeyValuePairNumber = {}; // TODO remove the redundancy with timers$
  currentTimerId = '';
  private timerIntervalSubscription: Subscription | null = null;
  timerWarningPoints: number[] = [];

  readonly windowFocusState$ = new Subject<WindowFocusState>(); // TODO why observable?

  private _navigationDenial$ = new Subject<{ sourceUnitSequenceId: number, reason: VeronaNavigationDeniedReason[] }>();

  get navigationDenial$(): Observable<{ sourceUnitSequenceId: number, reason: VeronaNavigationDeniedReason[] }> {
    return this._navigationDenial$;
  }

  private players: { [filename: string]: string } = {};
  private testState: { [key in TestStateKey]?: string } = {};

  sharedParameters: SharedParameter[] = [];

  navigation$: Subject<NavigationState> = new BehaviorSubject<NavigationState>({
    targets: {
      next: null,
      previous: null,
      first: null,
      last: null,
      end: null
    },
    directions: {
      forward: 'yes',
      backward: 'yes'
    }
  });

  private readonly bufferClosed$ = new Subject<string>();
  private readonly unitDataPartsBuffer$ = new Subject<UnitDataParts>();
  private readonly unitStateBuffer$ = new Subject<UnitStateUpdate>();
  private readonly testStateBuffer$ = new Subject<TestStateUpdate>();
  private readonly bufferFlushEventsOnClose$ = new Subject<BufferFlushEvent>();
  private readonly subscriptions: { [key: string]: Subscription } = {};

  constructor(
    private router: Router,
    private bs: BackendService,
    private ms: MessageService,
    private mds: MainDataService,
    private cts: CustomtextService,
    private messageService: MessageService,
    public confirmDialog: MatDialog
  ) {
    this.setupUnitDataPartsBuffer();
    this.setupUnitStateBuffer();
    this.setupTestStateBuffer();
  }

  setupUnitDataPartsBuffer(): void {
    this.destroySubscription('unitDataPartsBuffer'); // important when called from unit-test with fakeAsync

    const closingSignal = this.createClosingSignal('unit_responses_buffer_time');

    this.subscriptions.unitDataPartsBuffer = this.unitDataPartsBuffer$
      .pipe(
        bufferWhen(closingSignal.factory),
        map(TestStateUtil.sortDataParts),
        withLatestFrom(closingSignal.closingId$)
      )
      .subscribe(([buffer, closingId]) => {
        let trackedVariablesChanged = false;
        buffer
          .forEach(changedDataPartsPerUnit => {
            trackedVariablesChanged = this.updateVariables(
              this.unitAliasMap[changedDataPartsPerUnit.unitAlias],
              changedDataPartsPerUnit.unitStateDataType,
              changedDataPartsPerUnit.dataParts
            );
          });

        if (trackedVariablesChanged) {
          this.evaluateConditions();
        }

        this.bufferFlushEventsOnClose$.next({ type: 'unitData', event: 'closed', id: closingId });

        if (this.testMode.saveResponses) {
          forkJoin(
            buffer.map(changedDataPartsPerUnit => this.bs.updateDataParts(
              this.testId,
              changedDataPartsPerUnit.unitAlias,
              this.units[this.unitAliasMap[changedDataPartsPerUnit.unitAlias]].id,
              changedDataPartsPerUnit.dataParts,
              changedDataPartsPerUnit.unitStateDataType
            ))
          )
            .subscribe({
              complete: () => this.bufferFlushEventsOnClose$.next({ type: 'unitData', event: 'saved', id: closingId })
            });
        } else {
          this.bufferFlushEventsOnClose$.next({ type: 'unitData', event: 'saved', id: closingId });
        }
      });
  }

  private createClosingSignal(
    configSetting: keyof BookletConfig
  ): { closingId$: Observable<string>, factory: () => Observable<string> } {
    const closingId$ = new Subject<string>();

    const factory = () => {
      const closer$ = merge(
        timer(Number(this.booklet?.config[configSetting] || 100000)).pipe(map(() => configSetting)),
        this.bufferClosed$
      );
      // the calling site 'bufferWhen' doesn't expose what caused the close. Forwarding the closing value
      // into closingId$ lets withLatestFrom(closingId$) in each buffer pipe
      // retrieve which closingId triggered the flush alongside the buffered data.
      closer$.subscribe(closingId$);
      return closer$;
    };
    return { closingId$, factory };
  }

  setupUnitStateBuffer(): void {
    this.destroySubscription('unitStateBuffer');
    const closingSignal = this.createClosingSignal('unit_state_buffer_time');
    this.subscriptions.unitStateBuffer = this.unitStateBuffer$
      .pipe(
        bufferWhen(closingSignal.factory),
        map(TestStateUtil.sort),
        withLatestFrom(closingSignal.closingId$)
      )
      .subscribe(([buffer, closingId]) => {
        this.bufferFlushEventsOnClose$.next({ type: 'unitState', event: 'closed', id: closingId });
        if (!this.testMode.saveResponses) {
          this.bufferFlushEventsOnClose$.next({ type: 'unitState', event: 'saved', id: closingId });
        } else {
          from(buffer).pipe(
            concatMap(patch => this.bs.patchUnitState(patch, this.units[this.unitAliasMap[patch.unitAlias]].id))
          ).subscribe(
            {
              complete: () => this.bufferFlushEventsOnClose$.next({ type: 'unitState', event: 'saved', id: closingId })
            }
          );
        }
      });
  }

  setupTestStateBuffer(): void {
    this.destroySubscription('testStateBuffer');
    const closingSignal = this.createClosingSignal('test_state_buffer_time');
    this.subscriptions.testStateBuffer = this.testStateBuffer$
      .pipe(
        bufferWhen(closingSignal.factory),
        map(TestStateUtil.sort),
        withLatestFrom(closingSignal.closingId$)
      )
      .subscribe(([buffer, closingId]) => {
        this.bufferFlushEventsOnClose$.next({ type: 'testState', event: 'closed', id: closingId });
        if (!this.testMode.saveResponses) {
          this.bufferFlushEventsOnClose$.next({ type: 'testState', event: 'saved', id: closingId });
        } else {
          forkJoin(
            buffer
              .filter(patch => !!patch.testId)
              .map(patch => this.bs.patchTestState(patch))
          ).subscribe({
            complete: () => { this.bufferFlushEventsOnClose$.next({ type: 'testState', event: 'saved', id: closingId }); }
          });
        }
      });
  }

  addToTestStateBuffer(key: TestStateKey, content: string): void {
    if (this.testState[key] === content) return;
    this.testState[key] = content;
    this.testStateBuffer$.next(<TestStateUpdate>{
      testId: this.testId,
      unitAlias: '',
      state: [{ key, content, timeStamp: Date.now() }]
    });
  }

  destroySubscription(name: string): void {
    this.subscriptions[name]?.unsubscribe();
    delete this.subscriptions[name];
  }

  // todo when calling closeAllBuffers, the resulting closingSignalId could result in an empty array, because the timer flush could have already happened in the meantime. Check if it is critical to know who exactly is reponsible for flushing the buffers
  async closeAllBuffers(reasonType: string, trackEvent: BufferFlushEventType = 'closed'): Promise<NavigationState> {
    const closingSignalId = `${reasonType}:${Math.random()}`;

    const closingBufferListener = this.bufferFlushEventsOnClose$
      .pipe(
        scan(
          (agg, current) => {
            if ((current.id === closingSignalId) && (current.event === trackEvent)) {
              agg.add(current);
            }
            return agg;
          },
          new Set<BufferFlushEvent>()
        ),
        // After setting bufferClosed.next(), all three buffers will be closed, each emitting a 'closed' event and possibly a 'saved' event. Because closeAllBuffers() only tracks one kind of event, the happy path should produce N events of bufferTypes.length
        takeWhile(flushedBuffers => flushedBuffers.size < bufferTypes.length, true),
        withLatestFrom(this.navigation$),
        map(([_, navigation]) => navigation)
      );

    // setTimeout defers by one tick to ensure closingBufferListener is subscribed
    // before the bufferClosed$ signal is emitted, avoiding a race condition.
    setTimeout(() => this.bufferClosed$.next(closingSignalId));
    return lastValueFrom(closingBufferListener);
  }

  reset(): void {
    this.players = {};
    this.sharedParameters = [];

    this.currentUnitSequenceId = -Infinity;
    this.unitContentReady$.next(false);

    this.booklet = null;
    this.units = {};
    this.testlets = {};
    this.unitAliasMap = {};

    this.timerWarningPoints = [];
    this.workspaceId = 0;

    this.timers = {};
    this.testState = {};

    if (this.timerIntervalSubscription !== null) {
      this.timerIntervalSubscription.unsubscribe();
      this.timerIntervalSubscription = null;
    }
    this.currentTimerId = '';
  }

  AddToUnitStateDataPartsBuffer(unitSequenceId: number, dataParts: KeyValuePairString, unitStateDataType: string): void {
    const unit = this.getUnit(unitSequenceId);

    const changedParts: KeyValuePairString = {};
    Object.keys(dataParts)
      .forEach(dataPartId => {
        if (
          !unit.dataParts[dataPartId] ||
          (unit.dataParts[dataPartId] !== dataParts[dataPartId])
        ) {
          unit.dataParts[dataPartId] = dataParts[dataPartId];
          changedParts[dataPartId] = dataParts[dataPartId];
        }
      });
    if (Object.keys(changedParts).length) {
      this.unitDataPartsBuffer$.next({
        testId: this.testId,
        unitAlias: unit.alias,
        dataParts: changedParts,
        unitStateDataType
      });
    }
    this.updateNavigationState(); // now, not after buffer is closed, because it affects forward/backward, not choice
  }

  AddToUnitStateBuffer(unitSequenceId: number, unitStateUpdate: StateReportEntry<UnitStateKey>[]): void {
    const unit = this.getUnit(unitSequenceId);

    const setUnitState = (stateKey: string, value: string): void => {
      if (stateKey === 'RESPONSE_PROGRESS' && isVeronaProgress(value)) {
        unit.state.RESPONSE_PROGRESS = value;
      }

      if (stateKey === 'PRESENTATION_PROGRESS' && isVeronaProgress(value)) {
        unit.state.PRESENTATION_PROGRESS = value;
      }

      if (stateKey === 'CURRENT_PAGE_ID') {
        unit.state.CURRENT_PAGE_ID = value;
      }
    };

    const changedStates = unitStateUpdate
      .filter(state => !!state.content)
      .filter(changedState => {
        const oldState = unit.state[changedState.key];
        if (oldState) {
          return oldState !== changedState.content;
        }
        return true;
      });
    changedStates
      .forEach(changedState => setUnitState(changedState.key, changedState.content));
    if (changedStates.length) {
      this.unitStateBuffer$.next({
        unitAlias: unit.alias,
        testId: this.testId,
        state: changedStates
      });
    }
  }

  addPlayer(fileName: string, player: string): void {
    this.players[fileName] = player;
  }

  hasPlayer(fileName: string): boolean {
    return fileName in this.players;
  }

  getPlayer(fileName: string): string {
    return this.players[fileName];
  }

  clearCodeLock(testletId: string): void {
    if (!this.testlets[testletId] || !this.testlets[testletId].restrictions.codeToEnter?.code) {
      return;
    }
    this.updateSingleLock(this.testlets[testletId], 'code', false);
    const unlockedTestlets = Object.values(this.testlets)
      .filter(t => t.restrictions.codeToEnter?.code && !t.locks.code)
      .map(t => t.id);
    this.addToTestStateBuffer('TESTLETS_CLEARED_CODE', JSON.stringify(unlockedTestlets));
  }

  activateTestletLeaveLock(testletId: string): void {
    this.updateSingleLock(this.testlets[testletId], 'afterLeave', true);
    const lockedTestlets = Object.values(this.testlets)
      .filter(t => (t.restrictions.lockAfterLeaving?.scope === 'testlet') && t.locks.afterLeave)
      .map(t => t.id);
    this.addToTestStateBuffer('TESTLETS_LOCKED_AFTER_LEAVE', JSON.stringify(lockedTestlets));
  }

  activateUnitLeaveLock(unitSequenceId: number): void {
    this.units[unitSequenceId].lockedAfterLeaving = true;
    const lockedUnits = Object.values(this.units)
      .filter(u => (u.parent.restrictions.lockAfterLeaving?.scope === 'unit') && u.lockedAfterLeaving)
      .map(u => u.sequenceId);
    this.addToTestStateBuffer('UNITS_LOCKED_AFTER_LEAVE', JSON.stringify(lockedUnits));
  }

  getUnit(unitSequenceId: number): Unit {
    if (!this.booklet) { // when loading process was aborted
      throw new MissingBookletError();
    }
    const unit = this.units[unitSequenceId];

    if (!unit) {
      console.error(`Unit not found: ${unitSequenceId}`);
      throw new AppError({
        label: `Unit not found: ${unitSequenceId}`,
        description: '',
        type: 'script'
      });
    }
    return unit;
  }

  private getUnitBlockIds(sequenceId: number): number[] {
    const unit = this.getUnit(sequenceId);
    if (!unit.parent) {
      return [sequenceId];
    }
    const ids: number[] = [];
    const addChildren = (testlet: Testlet): void => {
      testlet.children.forEach(child => {
        if (isUnit(child)) {
          ids.push(child.sequenceId);
        } else {
          addChildren(child);
        }
      });
    };
    addChildren(unit.parent);
    return ids;
  }

  unitBlockResourcesLoaded$(sequenceId: number): Observable<LoadingProgress[]> {
    const resourcesToLoad = this.getUnitBlockIds(sequenceId)
      .flatMap(id => Object.values(this.getUnit(id).loadingProgress));
    return combineLatest(resourcesToLoad);
  }

  restoreTime(testlet: Testlet, timeGivenByGm: number): void {
    if (!testlet.restrictions?.timeMax) return;
    if (typeof this.timers[testlet.id] === 'undefined') return;
    if (this.timers[testlet.id] > 0) return;
    if (this.timers[testlet.id] <= 0) {
      this.timers[testlet.id] = timeGivenByGm;
    }
    this.updateSingleLock(testlet, 'time', false);
  }

  startTimer(testlet: Testlet): void {
    if (!testlet.restrictions?.timeMax) {
      return;
    }
    const timeLeftMinutes = (this.timers[testlet.id] && (this.timers[testlet.id] > 0)) ?
      Math.min(this.timers[testlet.id], testlet.restrictions.timeMax.minutes) :
      testlet.restrictions.timeMax.minutes;
    if (this.timerIntervalSubscription !== null) {
      this.timerIntervalSubscription.unsubscribe();
    }
    this.timers$.next(new TimerData(timeLeftMinutes, testlet.id, MaxTimerEvent.STARTED));
    this.currentTimerId = testlet.id;

    const timeTicker$ = createTicker();
    this.timerIntervalSubscription = timeTicker$
      .pipe(
        takeUntil(
          timer(timeLeftMinutes * 60 * 1000)
        ),
        map(val => (timeLeftMinutes * 60) - val - 1)
      ).subscribe({
        next: val => {
          this.timers$.next(new TimerData(val / 60, testlet.id, MaxTimerEvent.STEP));
        },
        error: e => {
          throw e;
        },
        complete: () => {
          this.timers$.next(new TimerData(0, testlet.id, MaxTimerEvent.ENDED));
          this.finishTimer();
        }
      });
  }

  private finishTimer() {
    if (this.timerIntervalSubscription !== null) {
      this.timerIntervalSubscription.unsubscribe();
    }
    this.timerIntervalSubscription = null;
    this.currentTimerId = '';
  }

  cancelTimer(): void {
    if (this.currentTimerId) {
      this.timers$.next(new TimerData(0, this.currentTimerId, MaxTimerEvent.CANCELLED));
    }
    this.finishTimer();
  }

  interruptTimer(): void {
    if (this.currentTimerId) {
      this.timers$.next(new TimerData(0, this.currentTimerId, MaxTimerEvent.INTERRUPTED));
    }
    this.finishTimer();
  }

  async terminateTest(logEntryKey: string, force: boolean, lockTest: boolean = false): Promise<boolean> {
    if (this.state$.getValue() === 'TERMINATED') return true; // sometimes terminateTest get called two times

    const navigationSuccessful = await lastValueFrom(this.canDeactivateUnit('/r/starter', force));
    if (!(navigationSuccessful || force)) return true;

    this.state$.next((this.state$.getValue() === 'PAUSED') ? 'TERMINATED_PAUSED' : 'TERMINATED');
    // todo race condition: between state$.next() and the subsequent closingBufferListener, the automatic test_state_buffer_time could already flush the testState. This is handled by complete() instead of next() but could be improved overall.
    await this.closeAllBuffers(`terminateTest:${logEntryKey}`, 'saved');

    if (lockTest) {
      await lastValueFrom(this.bs.lockTest(this.testId, Date.now(), logEntryKey));
    }

    return this.router.navigate(['/r/starter'], { state: { force: force } });
  }

  async executeGotoCommand(params: string[]): Promise<boolean> {
    this.state$.next('RUNNING');
    let gotoTarget = '';
    if ((params.length > 1) && (params[0] === 'id')) {
      gotoTarget = (this.unitAliasMap[params[1]]).toString(10);
    } else if (params.length >= 1) {
      gotoTarget = params[0];
    }
    if (gotoTarget && gotoTarget !== '0') {
      const targetUnit = this.units[parseInt(gotoTarget, 10)];
      if (targetUnit) {
        if (targetUnit.parent.timerId !== this.currentUnit?.parent.timerId) {
          this.cancelTimer();
          this.restoreTime(targetUnit.parent, parseInt(params[2].trim().split(' ').pop()!, 10));
        }
        this.updateSingleLock(targetUnit.parent, 'afterLeave', false);
        targetUnit.lockedAfterLeaving = false;
        this.clearCodeLock(targetUnit.parent.id);
      }
      return this.setUnitNavigationRequest(gotoTarget, true);
    }
    return Promise.reject();
  }

  async setUnitNavigationRequest(navString: string, force = false): Promise<boolean> {
    if (!this.booklet) {
      throw new AppError({
        label: 'Kein Booklet gefunden.',
        description: ''
      });
    }
    let navigation: NavigationState;
    switch (navString) {
    case UnitNavigationTarget.ERROR:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} NEXT`);
      this.messageService.showErrorDialog(this.cts.getCustomText('booklet_errormessage'));
      return false;
    case UnitNavigationTarget.PAUSE:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} NEXT`);
      return this.router.navigate([`/t/${this.testId}/status`], { skipLocationChange: true, state: { force } });
    case UnitNavigationTarget.NEXT:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} NEXT`);
      return this.router.navigate([`/t/${this.testId}/u/${navigation.targets.next}`], { state: { force } });
    case UnitNavigationTarget.PREVIOUS:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} PREVIOUS`);
      return this.router.navigate([`/t/${this.testId}/u/${navigation.targets.previous}`], { state: { force } });
    case UnitNavigationTarget.FIRST:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} FIRST`);
      return this.router.navigate([`/t/${this.testId}/u/${navigation.targets.first}`], { state: { force } });
    case UnitNavigationTarget.LAST:
      navigation = await this.closeAllBuffers(`setUnitNavigationRequest(${navString} LAST`);
      return this.router.navigate([`/t/${this.testId}/u/${navigation.targets.last}`], { state: { force } });
    case UnitNavigationTarget.END:
      return this.terminateTest(
        force ? 'BOOKLETLOCKEDforced' : 'BOOKLETLOCKEDbyTESTEE',
        force,
        this.booklet?.config.lock_test_on_termination === 'ON'
      );
    default:
      const targetIsCurrent = this.currentUnitSequenceId.toString(10) === navString;
      return this.router.navigate(
        [`/t/${this.testId}/u/${navString}`],
        {
          state: { force },
          queryParams: targetIsCurrent ? { reload: Date.now() >> 11 } : {}
          //  unit shall be reloaded even if we are there already there
        }
      )
        .then(navOk => {
          if (!navOk && !targetIsCurrent) {
            // happens when a goto goes to a unit which does exist, but is not accessible
            if (this.shouldShowConfirmationUI()) {
              this.ms.showSnackbar(`Navigation zu ${navString} nicht erlaubt.`);
            }
          }
          return navOk;
        });
    }
  }

  errorOut(): void {
    this.totalLoadingProgress = 0;
    this.state$.next('ERROR');
    this.setUnitNavigationRequest(UnitNavigationTarget.ERROR);
  }

  pause(): Promise<boolean> {
    this.interruptTimer();
    this.state$.next('PAUSED');
    return this.setUnitNavigationRequest(UnitNavigationTarget.PAUSE, true);
  }

  resume(): Promise<boolean> {
    const target = (this.currentUnitSequenceId > 0) ? String(this.currentUnitSequenceId) : UnitNavigationTarget.FIRST;
    this.state$.next('RUNNING');
    return this.setUnitNavigationRequest(target, true);
  }

  updateSingleLock(testlet: Testlet, key: TestletLockType, value: boolean): void {
    testlet.locks[key] = value;
    this.updateAllLocks();
  }

  updateAllLocks(): void {
    const activatedLockTypes = TestletLockTypes;

    const updateLocks = (testlet: Testlet, parents: Testlet[] = []): void => {
      testlet.locked = [...parents, testlet]
        .flatMap(item => activatedLockTypes.map(lockType => ({ through: item, by: lockType })))
        .find(isLocked => isLocked.through.locks[isLocked.by]) || null;
      testlet.children
        .filter(isTestlet)
        .forEach(child => updateLocks(child, [...parents, testlet]));
    };

    if (!this.booklet) {
      return;
    }

    updateLocks(this.testlets[this.booklet.units.id]);
    this.updateNavigationState();
  }

  updateNavigationState(): void {
    if (!this.currentUnitSequenceId) return;
    this.navigation$.next(this.getNavigationState(this.currentUnitSequenceId));
  }

  getNavigationState(fromUnitSequenceId: number): NavigationState {
    let unit: Unit;
    let first = null;
    // eslint-disable-next-line @typescript-eslint/no-shadow
    let last = null;
    let previous = null;
    let next = null;
    for (let sequenceId = 1; sequenceId <= Object.keys(this.units).length; sequenceId++) {
      unit = this.units[sequenceId];
      if (!TestControllerService.unitIsInaccessible(unit)) {
        last = unit.sequenceId;
        if (sequenceId > fromUnitSequenceId && next === null) {
          next = unit.sequenceId;
        }
        if (first === null) {
          first = unit.sequenceId;
        }
        if (sequenceId < fromUnitSequenceId) {
          previous = unit.sequenceId;
        }
      }
    }
    const end = (this.booklet?.config.allow_player_to_terminate_test === 'ON') ||
    ((this.booklet?.config.allow_player_to_terminate_test === 'LAST_UNIT') && (fromUnitSequenceId === last)) ?
      Infinity :
      null;

    let forward: NavigationDirectionValue = next !== null ? 'yes' : 'no';
    let backward: NavigationDirectionValue = previous !== null ? 'yes' : 'no';
    if (this.currentUnit && this.checkCompleteness(this.currentUnit, 'forward').length) {
      forward = 'markedNo';
    }
    if (this.currentUnit && this.checkCompleteness(this.currentUnit, 'backward').length) {
      backward = 'markedNo';
    }

    first = previous;

    return {
      directions: { forward, backward },
      targets: {
        next, previous, first, last, end
      }
    };
  }

  checkCompleteness(unit: Unit, direction: NavigationDirection): VeronaNavigationDeniedReason[] {
    if (unit.parent.locked || unit.lockedAfterLeaving) {
      return [];
    }
    const reasons: VeronaNavigationDeniedReason[] = [];
    const checkOnValue = {
      forward: <NavigationLeaveRestrictionValue[]>['ON', 'ALWAYS'],
      backward: <NavigationLeaveRestrictionValue[]>['ALWAYS']
    };
    const presentationCompleteRequired =
      unit.parent?.restrictions?.denyNavigationOnIncomplete?.presentation ||
      this.booklet?.config.force_presentation_complete ||
      'OFF';
    if (
      (checkOnValue[direction].includes(presentationCompleteRequired)) &&
      (unit.state.PRESENTATION_PROGRESS !== 'complete')
    ) {
      reasons.push('presentationIncomplete');
    }
    const responseCompleteRequired =
      unit.parent?.restrictions?.denyNavigationOnIncomplete?.response ||
      this.booklet?.config.force_response_complete ||
      'OFF';
    if (
      (checkOnValue[direction].includes(responseCompleteRequired)) &&
      unit.state.RESPONSE_PROGRESS &&
      (VeronaProgressIncompleteValues.includes(unit.state.RESPONSE_PROGRESS))
    ) {
      reasons.push('responsesIncomplete');
    }
    return reasons;
  }

  static unitIsInaccessible(unit: Unit): boolean {
    if (unit.lockedAfterLeaving) return true;
    if (!unit.parent.locked) return false;
    if (
      (unit.parent.locked.by === 'code') &&
      (unit.localIndex === 0) &&
      (!unit.parent.locks.show) &&
      (!unit.parent.locks.time) &&
      (!unit.parent.locks.afterLeave)
    ) return false; // allow it to enter the first unit of a code-locked block to enter the code
    return true;
  }

  updateVariables(
    sequenceId: number,
    unitStateDataType: string = this.units[sequenceId].responseType || 'unknown',
    dataParts: KeyValuePairString = this.units[sequenceId].dataParts
  ): boolean {
    const isIqbStandard = unitStateDataType.match(/iqb-standard@(\d+)/);
    const iqbStandardVersion = isIqbStandard ? Number(isIqbStandard[1]) : 0;
    if (
      iqbStandardVersion < (this.mds.appConfig?.iqbStandardResponseTypeMin || NaN) ||
      iqbStandardVersion > (this.mds.appConfig?.iqbStandardResponseTypeMax || NaN)
    ) {
      return false;
    }
    const trackedVariables = Object.keys(this.units[sequenceId].variables);
    if (!trackedVariables.length) {
      return false;
    }

    const filterRegex = new RegExp(
      trackedVariables
        .map(varn => `"id":\\s*"${varn.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}"`)
        .join('|')
    );

    let somethingChanged = false;
    Object.values(dataParts)
      .forEach(dataPart => {
        if (!dataPart.match(filterRegex)) {
          // for the sake of performance we check the appearance of the tracked variable in the chunk before JSON.parse
          // see commit message for details
          return;
        }
        const data = JSON.parse(dataPart);
        if (!Array.isArray(data)) {
          return;
        }
        data
          .forEach(variable => {
            if (!isIQBVariable(variable)) {
              return;
            }
            if (typeof this.units[sequenceId].variables[variable.id] === 'undefined') {
              // variable is not tracked
              return;
            }

            if (
              this.units[sequenceId].variables[variable.id].status === variable.status &&
              this.units[sequenceId].variables[variable.id].value === variable.value &&
              this.units[sequenceId].variables[variable.id].code === variable.code &&
              this.units[sequenceId].variables[variable.id].score === variable.score
            ) {
              // nothing has actually changed
              return;
            }

            this.units[sequenceId].variables[variable.id] = variable;
            somethingChanged = true;
          });
      });
    if (somethingChanged && this.units[sequenceId].scheme.length) {
      this.codeVariables(sequenceId);
    }

    return somethingChanged;
  }

  private codeVariables(sequenceId: number): void {
    const baseVars = Object.values(this.units[sequenceId].variables)
      .filter(vari => this.units[sequenceId].baseVariableIds.includes(vari.id));
    CodingSchemeFactory.code(baseVars, this.units[sequenceId].scheme)
      .forEach(variable => {
        if (variable.id in this.units[sequenceId].variables) {
          this.units[sequenceId].variables[variable.id] = variable;
        }
      });
  }

  evaluateConditions(): void {
    this.updateStates();
    this.onStateOptionChanged();
  }

  onStateOptionChanged(): void {
    this.updateAllShowLocks();
    this.saveConditionsTestState();
  }

  private updateStates(): void {
    if (!this.booklet?.states) return;
    const getVar =
      (unitAlias: string, variableId: string) => this.units[this.unitAliasMap[unitAlias]].variables[variableId];
    Object.values(this.booklet.states)
      .forEach(state => {
        const firstMatchingOption =
          Object.values(state.options)
            .find(option => {
              option.firstUnsatisfiedCondition =
                option.conditions
                  .findIndex(condition => !ConditionUtil.isSatisfied(condition, getVar));
              return option.firstUnsatisfiedCondition === -1;
            });
        state.current = firstMatchingOption?.id || state.options[Object.keys(state.options).length - 1].id;
      });
  }

  private updateAllShowLocks(): void {
    Object.values(this.testlets)
      .forEach(testlet => {
        if (!testlet.restrictions.show) return;
        const current =
          this.booklet?.states[testlet.restrictions.show.if].override ||
          this.booklet?.states[testlet.restrictions.show.if].current;
        testlet.locks.show = current !== testlet.restrictions.show.is;
      });
    this.updateAllLocks();
  }

  private saveConditionsTestState(): void {
    const bookletStates = Object.values(this.booklet?.states || {})
      .reduce(
        (agg, state) => {
          agg[state.id] = state.override || state.current;
          return agg;
        }, <{ [state: string]: string }>{});
    if (!Object.keys(bookletStates).length) return;
    this.addToTestStateBuffer('BOOKLET_STATES', JSON.stringify(bookletStates));
  }

  private checkAndSolveTimer(currentUnit: Unit, newUnit: Unit | null): Observable<LeaveCheckResult> {
    if (!this.currentTimerId) { // leaving unit is not in a timed block
      return of({ kind: 'allow' });
    }

    if (newUnit && newUnit.parent.timerId && // staying in the same timed block
      (newUnit.parent.timerId === this.currentTimerId)
    ) {
      return of({ kind: 'allow' });
    }

    // when time restrictions aren't enforced (test/preview mode), interrupt the timer and let the
    // caller show an informational toast instead of actually blocking/asking
    const allowWithNotice = (text: string): LeaveCheckResult => {
      this.interruptTimer();
      return { kind: 'allow', notify: text };
    };

    if (this.testlets[this.currentTimerId].restrictions.timeMax?.leave === 'forbidden') {
      if (!this.testMode.forceTimeRestrictions) {
        return of(allowWithNotice('Im Testmodus wäre die Navigation vor Ablauf der Zeit nicht möglich.'));
      }
      return of({ kind: 'deny', notify: 'Es darf erst weiter geblättert werden, wenn die Zeit abgelaufen ist.' });
    }

    if (this.testlets[this.currentTimerId].restrictions.timeMax?.leave === 'allowed') {
      this.cancelTimer();
      return of({ kind: 'allow' });
    }

    if (!this.testMode.forceTimeRestrictions) {
      return of(allowWithNotice(
        'Im normalen Testablauf wird beim Verlassen des zeitbegrenzten Blocks eine Warnung angezeigt.'
      ));
    }

    return of({
      kind: 'confirm',
      title: this.cts.getCustomText('booklet_warningLeaveTimerBlockTitle'),
      content: this.cts.getCustomText('booklet_warningLeaveTimerBlockTextPrompt'),
      onConfirmed: () => { this.cancelTimer(); return undefined; } // does lock the block
    });
  }

  private checkAndSolveCompleteness(currentUnit: Unit, newUnit: Unit | null): Observable<LeaveCheckResult> {
    const direction = (!newUnit || currentUnit.sequenceId < newUnit.sequenceId) ? 'forward' : 'backward';
    const reasons = this.checkCompleteness(currentUnit, direction);

    // if no testlet has no DenyNavigationOnIncomplete defined
    if (!reasons.length) {
      return of({ kind: 'allow' });
    }

    if (!this.testMode.forceNaviRestrictions) {
      const reasonTexts = {
        presentationIncomplete: 'Es wurde nicht alles gesehen oder abgespielt.',
        responsesIncomplete: 'Es wurde nicht alles bearbeitet.'
      };
      return of({
        kind: 'allow',
        notify: `Im Testmodus dürfte hier nicht ${(direction === 'forward') ? 'weiter' : ' zurück'} geblättert
      werden: ${reasons.map(r => reasonTexts[r]).join(' ')}`
      });
    }

    this._navigationDenial$.next({ sourceUnitSequenceId: currentUnit.sequenceId, reason: reasons });

    return of({
      kind: 'deny',
      infoDialog: {
        title: this.cts.getCustomText('booklet_msgNavigationDeniedTitle'),
        content: reasons
          .map(r => this.cts.getCustomText(`booklet_msgNavigationDeniedText_${r}`))
          .join(' ')
      }
    });
  }

  private checkAndSolveLeaveLocks(currentUnit: Unit, newUnit: Unit | null): Observable<LeaveCheckResult> {
    // no lockAfterLeaving defined for testlet
    if (!currentUnit.parent.restrictions.lockAfterLeaving) {
      return of({ kind: 'allow' });
    }

    const lockScope = currentUnit.parent.restrictions.lockAfterLeaving.scope;
    const leaveLock = (): string | undefined => {
      if (this.testMode.forceNaviRestrictions) {
        if (lockScope === 'testlet') {
          this.activateTestletLeaveLock(currentUnit.parent.id);
        }
        if (lockScope === 'unit') {
          this.activateUnitLeaveLock(currentUnit.sequenceId);
        }
        return undefined;
      }
      return `${lockScope} würde im Testmodus nun gesperrt werden.`;
    };

    if ((lockScope === 'testlet') && (newUnit?.parent.id === currentUnit.parent.id)) {
      return of({ kind: 'allow' });
    }

    if (currentUnit.parent.restrictions.lockAfterLeaving.confirm) {
      return of({
        kind: 'confirm',
        title: this.cts.getCustomText(`booklet_warningLeaveTitle-${lockScope}`),
        content: this.cts.getCustomText(`booklet_warningLeaveTextPrompt-${lockScope}`),
        onConfirmed: () => leaveLock()
      });
    }

    return of({ kind: 'allow', notify: leaveLock() });
  }

  // The only place that calls MessageService for the three checks above - shows whatever they
  // decided (confirm dialog / info dialog / nothing) and resolves the final true/false.
  //
  // `alsoEndsTest` (see willAlsoEndTest) is true when this navigation would, by itself, also end
  // the whole test - not just leave the current unit. TestControllerDeactivateGuard normally asks
  // its own separate "end the test?" question for that; when a 'confirm' result ends up showing a
  // dialog here anyway, we fold that into THIS dialog (one confirm covers both) instead of leaving
  // it to a second, separate one right after
  private resolveLeaveCheckResult(result: LeaveCheckResult, alsoEndsTest: boolean): Observable<boolean> {
    switch (result.kind) {
      case 'allow':
        return of(true);
      case 'deny':
        return result.infoDialog ?
          this.messageService.showInfoDialog(result.infoDialog).pipe(map(() => false)) :
          of(false);
      case 'confirm':
        return this.messageService.showConfirmDialog({
          title: alsoEndsTest ? 'Sicher, dass du den Test beenden möchtest?' : result.title,
          content: result.content,
          confirmText: 'Hier bleiben',
          cancelText: 'Trotzdem weiter'
        }).pipe(
          concatMap(cdresult => {
            if (cdresult !== false) {
              return of(false); // user chose "Hier bleiben" - stay
            }
            const followUpNotify = result.onConfirmed();
            if (followUpNotify) {
              this.ms.showSnackbar(followUpNotify);
            }
            if (!alsoEndsTest) {
              return of(true);
            }
            // terminateConfirmedLeave() transitions state$ away from RUNNING/PAUSED before this
            // resolves, so confirmEndTestIfNeeded() (called next, by TestControllerDeactivateGuard)
            // will see that and skip its own dialog/termination.
            return from(this.terminateConfirmedLeave()).pipe(map(() => true));
          })
        );
      default:
        return of(true);
    }
  }

  canDeactivateUnit(nextStateUrl: string, ignoreRouterState?: boolean): Observable<boolean> {
    if (this.state$.getValue() === 'ERROR') {
      return of(true);
    }

    if (!this.currentUnit) {
      return of(true);
    }

    const currentUnit = this.currentUnit;

    if (this.currentUnit.parent.locked) {
      return of(true);
    }

    let newUnit: Unit | null = null;
    const match = nextStateUrl.match(/t\/(\d+)\/u\/(\d+)$/);
    if (match) {
      const targetUnitSequenceId = Number(match[2]);
      newUnit = this.units[targetUnitSequenceId] || null;
    }

    const forceNavigation = ignoreRouterState ?? this.router.getCurrentNavigation()?.extras?.state?.force ?? false;
    if (forceNavigation) {
      this.interruptTimer();
      return of(true);
    }

    const alsoEndsTest = this.willAlsoEndTest(nextStateUrl);

    return from([
      this.checkAndSolveCompleteness.bind(this),
      this.checkAndSolveTimer.bind(this),
      this.checkAndSolveLeaveLocks.bind(this)
    ])
      .pipe(
        concatMap(check => check(currentUnit, newUnit)),
        // show each check's own FYI toast (`result.notify`) as it flows through, in order - not
        // just the last one's, since an earlier check's "allow" can carry a notice even when a
        // later check goes on to decide the final outcome
        tap(result => { if (result.kind !== 'confirm' && result.notify) this.ms.showSnackbar(result.notify); }),
        takeWhile(result => result.kind === 'allow', true),
        last(),
        concatMap(result => this.resolveLeaveCheckResult(result, alsoEndsTest))
      );
  }

  // Whether navigating to `nextStateUrl` would also end the test - not just leave the current unit.
  willAlsoEndTest(nextStateUrl: string): boolean {
    if (!this.testMode.saveResponses) {
      return false;
    }
    // parse the URL through Angular's own router; the segment
    // structure mirrors app-routing.module.ts's `{ path: 't', ... }`
    const firstSegment = this.router.parseUrl(nextStateUrl).root.children[PRIMARY_OUTLET]?.segments[0]?.path;
    if (firstSegment === 't') {
      return false; // still inside the running test, not actually exiting it
    }
    const testStatus = this.state$.getValue();
    const ignorePause = this.shouldShowConfirmationUI();
    return (testStatus === 'RUNNING') || (testStatus === 'PAUSED' && !ignorePause);
  }

  // Both UnitDeactivateGuard and TestControllerDeactivateGuard call this - instead of
  // canDeactivateUnit directly - whenever the navigation is leaving a unit page.
  // So without sharing this exact check - and its result - both guards could independently run
  // the checks above and pop their dialogs on top of one another. `shareReplay(1)` makes sure the
  // underlying checks - and any dialog they show - only run once, no matter which guard
  // subscribes first or how many do. Keyed by the current navigation's id (not the URL) so a
  // *later*, unrelated navigation to the same URL always gets a fresh check instead of a stale
  // cached result.
  private pendingUnitDeactivationCheck: { navigationId: number; result$: Observable<boolean> } | null = null;

  getUnitDeactivationCheck(nextStateUrl: string): Observable<boolean> {
    const navigationId = this.router.getCurrentNavigation()?.id ?? -1;
    if (!this.pendingUnitDeactivationCheck || this.pendingUnitDeactivationCheck.navigationId !== navigationId) {
      this.pendingUnitDeactivationCheck = {
        navigationId,
        result$: this.canDeactivateUnit(nextStateUrl).pipe(shareReplay(1))
      };
    }
    return this.pendingUnitDeactivationCheck.result$;
  }

  // Terminates the test as a consequence of the user confirming they want to leave/end it.
  private async terminateConfirmedLeave(): Promise<void> {
    await this.closeAllBuffers(`setUnitNavigationRequest(${UnitNavigationTarget.PAUSE} NEXT`);
    await this.terminateTest(
      'BOOKLETLOCKEDbyTESTEE', true, this.booklet?.config.lock_test_on_termination === 'ON'
    );
    this.cts.restoreDefault(false);
  }

  async confirmEndTestIfNeeded(): Promise<boolean> {
    if (this.testMode.saveResponses) {
      const testStatus: TestControllerState = this.state$.getValue();
      // at this moment in time, hideConfirmationUI comes with ignorePause for Logo Navigation
      const ignorePause = this.shouldShowConfirmationUI();
      if ((testStatus === 'RUNNING') || (testStatus === 'PAUSED' && !ignorePause)) {
        // this whole inner block mimics setUnitNavigationRequest(PAUSE), without manually triggering router.navigate()
        // in order to correctly return a redirect, instead of hacking (router.navigate + return false)
        if (!this.booklet) {
          throw new AppError({
            label: 'Kein Booklet gefunden.',
            description: ''
          });
        }
        const isLeaveConfirmed = await firstValueFrom(
          this.messageService.showConfirmDialog({
            title: 'Sicher, dass du den Test beenden möchtest?',
            content: ''
          })
        );
        if (isLeaveConfirmed) {
          await this.terminateConfirmedLeave();
        }
        return isLeaveConfirmed;
      }
    }
    return true;
  }

  shouldShowConfirmationUI(): boolean {
    return !(this.booklet?.config.silent_mode === 'TRUE' &&
           (this.testMode.forceTimeRestrictions || this.testMode.forceNaviRestrictions));
  }

  addSharedParameters(parameters: SharedParameter[]) {
    if (!Array.isArray(parameters) || !parameters.length) return;

    let hasChanged = false;

    parameters.forEach(param => {
      if (param.key && param.value) {
        hasChanged = this.addSharedParameter(param.key, param.value) || hasChanged;
      }
    });

    if (hasChanged) {
      this.addToTestStateBuffer('SHARED_PARAMETERS', JSON.stringify(this.sharedParameters));
      this.configChanged$.next();
    }
  }

  private addSharedParameter(key: string, value: string): boolean {
    let hasChanged = false;
    const existingParam = this.sharedParameters.find(p => p.key === key);

    if (existingParam) {
      existingParam.value = value;
      hasChanged = existingParam.value !== value;
    } else {
      const newParameter: SharedParameter = {
        key: key,
        value: value
      };
      this.sharedParameters.push(newParameter);
      hasChanged = true;
    }

    return hasChanged;
  }
}

import { ActivatedRoute } from '@angular/router';
import {
  Component, HostListener, Inject, OnDestroy, OnInit, ViewChild
} from '@angular/core';
import { combineLatest, Observable, Subscription } from 'rxjs';
import {
  debounceTime, distinctUntilChanged, filter, map
} from 'rxjs/operators';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { HeaderService } from '@shared/services/header.service';
import {
  CustomtextService, MainDataService, BackendService as SharedBackendService
} from '../../../shared/shared.module';
import {
  Command, MaxTimerEvent, NavControlContext, NavigationState, Unit,
  UnitNavigationTarget, WindowFocusState
} from '../../interfaces/test-controller.interfaces';
import { BackendService } from '../../services/backend.service';
import { TestControllerService } from '../../services/test-controller.service';
import { CommandService } from '../../services/command.service';
import { TestLoaderService } from '../../services/test-loader.service';
import { TimerData } from '../../classes/test-controller.classes';
import { MissingBookletError } from '../../classes/missing-booklet-error.class';
import { ReviewPanelComponent } from '../review-panel/review-panel.component';
import { PageService } from '../../services/page.service';
import { VeronaAPIService } from '../../services/verona-api.service';
import { MessageService } from '@shared/services/message.service';

@Component({
  templateUrl: './test-controller.component.html',
  styleUrls: ['./test-controller.component.css'],
  standalone: false
})
export class TestControllerComponent implements OnInit, OnDestroy {
  @ViewChild(ReviewPanelComponent) reviewComponent?: ReviewPanelComponent;

  private subscriptions: { [key: string]: Subscription | null } = {
    errorReporting: null,
    testStatus: null,
    routing: null,
    appWindowHasFocus: null,
    appFocus: null,
    command: null,
    maxTimer: null,
    connectionStatus: null
  };

  timerValue: TimerData | null = null;

  debugPane = false;
  sideNavContent: 'unit-menu' | 'review-form' = 'unit-menu';

  currentUnit: Unit | null = null;
  toolbarUnitLabel = '';

  unitNavContext: NavControlContext = {
    labelMode: 'INDEX',
    label: '',
    currentIndex: 0,
    maxIndex: 0
  };

  pageNavContext: NavControlContext = {
    labelMode: 'INDEX',
    label: '',
    currentIndex: 0,
    maxIndex: 0
  };

  constructor(public mainDataService: MainDataService,
              public tcs: TestControllerService,
              private bs: BackendService,
              private sharedBs: SharedBackendService,
              private snackBar: MatSnackBar,
              private route: ActivatedRoute,
              private cts: CustomtextService,
              public cmd: CommandService,
              private tls: TestLoaderService,
              public dialog: MatDialog,
              private headerService: HeaderService,
              public pageService: PageService,
              private apiService: VeronaAPIService,
              private messageService: MessageService,
              @Inject('IS_PRODUCTION_MODE') public isProductionMode: boolean) { }

  // Whether there is currently nothing ready to show to the testee yet: either the test itself is
  // still (re)loading, or - once routed to a unit - that unit's own block resources are still
  // loading (see TestControllerService.unitContentReady$). Drives both the shared loading overlay
  // in the template below and hiding the navigation controls (which would otherwise reference
  // not-yet-populated navigation state) until there is something to navigate.
  readonly isLoading$: Observable<boolean> = combineLatest([this.tcs.state$, this.tcs.unitContentReady$]).pipe(
    map(([state, unitContentReady]) => state === 'LOADING' || (state === 'RUNNING' && !unitContentReady))
  );

  ngOnInit(): void {
    setTimeout(() => {
      this.mainDataService.clearErrorBuffer();
      this.subscriptions.errorReporting = this.mainDataService.appError$
        .pipe(filter(e => !!e))
        .subscribe(() => this.tcs.errorOut());

      this.subscriptions.testStatus = this.tcs.state$
        .pipe(distinctUntilChanged())
        .subscribe(status => this.tcs.addToTestStateBuffer('CONTROLLER', status));

      this.subscriptions.appWindowHasFocus = this.mainDataService.appWindowHasFocus$
        .subscribe(hasFocus => {
          this.tcs.windowFocusState$.next(hasFocus ? 'HOST' : 'UNKNOWN');
        });

      this.subscriptions.command = this.cmd.command$
        .pipe(
          distinctUntilChanged((command1: Command, command2: Command): boolean => (command1.id === command2.id))
        )
        .subscribe((command: Command) => {
          this.handleCommand(command.keyword, command.arguments)
            .then(() => {
              this.bs.addTestLog(this.tcs.testId, [{
                key: 'command executed',
                timeStamp: Date.now(),
                content: CommandService.commandToString(command)
              }]);
            });
        });

      this.subscriptions.routing = this.route.params
        .subscribe(async params => {
          this.tcs.testId = params.t;
          try {
            await this.tls.loadTest();
            // set all visual flags from booklet configs
            this.showGlobalBack = this.deriveGlobalBack();
            this.showGlobalForward = this.deriveGlobalForward();
          } catch (err) {
            if (err instanceof MissingBookletError) { // this happens when loading was aborted.
              // eslint-disable-next-line no-console
              console.error(err); // don't swallow error entirely for the case, rootTestlet is missing in loading
              return;
            }
            await Promise.reject(err);
            return;
          }
          this.startAppFocusLogging();
          this.startConnectionStatusLogging();
          if (this.tcs.booklet?.config.ask_for_fullscreen !== 'OFF') {
            await this.requestFullScreen();
          }
        });

      this.subscriptions.maxTimer = this.tcs.timers$
        .subscribe(maxTimerEvent => this.handleTimer(maxTimerEvent));

      if (!this.isProductionMode) {
        this.debugPane = !!localStorage.getItem('tc-debug');
      }

      this.tcs.currentUnitSequenceId$.subscribe(() => {
        this.currentUnit = this.tcs.currentUnit;
        const unitLabel = this.currentUnit?.label || '';
        const unitLabelShort = this.currentUnit?.labelShort || unitLabel;
        this.toolbarUnitLabel = (this.tcs.booklet?.config.toolbar_unit_label === 'LABEL_SHORT') ?
          unitLabelShort :
          unitLabel;

        let navbarUnitLabel = unitLabel;
        if (this.tcs.booklet?.config.navbar_unit_label === 'INDEX') navbarUnitLabel = 'Aufgabe';
        if (this.tcs.booklet?.config.navbar_unit_label === 'LABEL_SHORT') navbarUnitLabel = unitLabelShort;
        this.unitNavContext = {
          labelMode: (this.tcs.booklet?.config.navbar_unit_label === 'INDEX') ? 'INDEX' : 'LABEL',
          readonly: (this.tcs.booklet?.config.navbar_unit_controls_hidden === 'TRUE'),
          label: navbarUnitLabel,
          currentIndex: this.tcs.currentUnitSequenceId - 1,
          maxIndex: Object.keys(this.tcs.units).length
        };

        if (this.tcs.booklet?.config.header_hidden === 'TRUE') {
          this.headerService.isHeaderHidden = true;
        } else {
          switch (this.tcs.booklet?.config.header_content) {
          case 'NONE':
            this.headerService.title = '';
            break;
          case 'BLOCK_LABEL':
            this.headerService.title = this.currentUnit?.parent.label;
            break;
          case 'BOOKLET_LABEL':
            this.headerService.title = this.tcs.booklet?.metadata.label;
            break;
          case 'UNIT_LABEL':
            this.headerService.title = unitLabel;
            break;
          case 'UNIT_LABEL_SHORT':
            this.headerService.title = unitLabelShort;
            break;
          // no default
          }
        }
      });
      this.tcs.navigation$.subscribe((nav: NavigationState) => {
        this.unitNavContext.isBackwardAllowed = nav.directions.backward !== 'no';
        this.unitNavContext.isForwardAllowed = nav.directions.forward !== 'no';
      });
      this.pageService.pagesUpdated.subscribe(() => {
        this.pageNavContext = {
          labelMode: this.tcs.booklet?.config.navbar_page_label || 'INDEX',
          readonly: (this.tcs.booklet?.config.navbar_page_controls_hidden === 'TRUE'),
          label: (this.tcs.booklet?.config.navbar_page_label === 'LABEL') ?
            this.pageService.getCurrentPage()?.label || '' :
            'Teilaufgabe',
          currentIndex: this.pageService.currentPageIndex,
          maxIndex: this.pageService.pages.length,
          isForwardAllowed: !this.pageService.isLastPage(),
          isBackwardAllowed: !this.pageService.isFirstPage()
        };
      });
    });
  }

  reload() {
    this.sharedBs.clearCache('cache').subscribe();
    // @ts-ignore: force reload with 'true' only works for firefox so far, that's why we clear cache manually
    setTimeout(() => { window.location.reload(true); }, 100);
  }

  private startAppFocusLogging() {
    if (!this.tcs.testMode.saveResponses) {
      return;
    }
    if (this.subscriptions.appFocus !== null) {
      this.subscriptions.appFocus.unsubscribe();
    }
    this.subscriptions.appFocus = this.tcs.windowFocusState$.pipe(
      debounceTime(500)
    ).subscribe((newState: WindowFocusState) => {
      if (['ERROR', 'TERMINATED'].includes(this.tcs.state$.getValue())) {
        return;
      }
      if (newState === 'UNKNOWN') {
        this.tcs.addToTestStateBuffer('FOCUS', 'HAS_NOT');
      } else {
        this.tcs.addToTestStateBuffer('FOCUS', 'HAS');
      }
    });
  }

  private startConnectionStatusLogging() {
    this.subscriptions.connectionStatus = this.cmd.connectionStatus$
      .pipe(
        map(status => status === 'ws-online'),
        distinctUntilChanged()
      )
      .subscribe(isWsConnected => {
        this.tcs.addToTestStateBuffer('CONNECTION', isWsConnected ? 'WEBSOCKET' : 'POLLING');
      });
  }

  handleCommand(commandName: string, params: string[]): Promise<boolean> {
    switch (commandName.toLowerCase()) {
      case 'debug':
        return this.toggleDebugPane(params);
      case 'pause':
        return this.tcs.pause();
      case 'resume':
        return this.tcs.resume();
      case 'terminate':
        return this.tcs.terminateTest('BOOKLETLOCKEDbyOPERATOR', true, params.indexOf('lock') > -1);
      case 'goto':
        return this.goto(params);
      default:
        return Promise.reject();
    }
  }

  private goto(params: string[]): Promise<boolean> {
    this.tcs.state$.next('RUNNING');
    // eslint-disable-next-line no-case-declarations
    let gotoTarget: string = '';
    if ((params.length > 1) && (params[0] === 'id')) {
      gotoTarget = (this.tcs.unitAliasMap[params[1]]).toString(10);
    } else if (params.length === 1) {
      gotoTarget = params[0];
    }
    if (gotoTarget && gotoTarget !== '0') {
      const targetUnit = this.tcs.units[parseInt(gotoTarget, 10)];
      if (targetUnit) {
        if (targetUnit.parent.timerId !== this.tcs.currentUnit?.parent.timerId) {
          this.tcs.cancelTimer();
          // parse the last word as integer
          this.tcs.restoreTime(targetUnit.parent, parseInt(params[2].trim().split(' ').pop()!, 10));
        }
        this.tcs.updateSingleLock(targetUnit.parent, 'afterLeave', false);
        targetUnit.lockedAfterLeaving = false;
        this.tcs.clearCodeLock(targetUnit.parent.id);
      }
      return this.tcs.setUnitNavigationRequest(gotoTarget, true);
    }
    return Promise.reject();
  }

  private toggleDebugPane(params: string[]): Promise<boolean> {
    this.debugPane = params.length === 0 || params[0].toLowerCase() !== 'off';
    if (this.debugPane) {
      localStorage.setItem('tc-debug', '["main"]');
    } else {
      localStorage.removeItem('tc-debug');
    }
    return Promise.resolve(true);
  }

  private async handleTimer(timer: TimerData): Promise<boolean> {
    const minute = timer.timeLeftSeconds / 60;
    switch (timer.type) {
      case MaxTimerEvent.STARTED:
        if (this.tcs.shouldShowConfirmationUI()) {
          this.snackBar.open(this.cts.getCustomText('booklet_msgTimerStarted') + timer.timeLeftMinString, '', {
            duration: 5000,
            panelClass: ['snackbar-time-started']
          });
        }
        this.timerValue = timer;
        this.tcs.timers[timer.id] = timer.timeLeftSeconds / 60;
        this.tcs.addToTestStateBuffer('TESTLETS_TIMELEFT', JSON.stringify(this.tcs.timers));
        return true;
      case MaxTimerEvent.ENDED:
        if (this.tcs.shouldShowConfirmationUI()) {
          this.snackBar.open(this.cts.getCustomText('booklet_msgTimeOver'), '', {
            duration: 5000,
            panelClass: ['snackbar-time-ended']
          });
        }
        this.tcs.timers[timer.id] = 0;
        // attention: TODO store timer as well in localStorage to prevent F5-cheating
        this.tcs.addToTestStateBuffer('TESTLETS_TIMELEFT', JSON.stringify(this.tcs.timers));
        this.timerValue = null;
        if (this.tcs.testMode.forceTimeRestrictions) {
          if (this.tcs.currentUnit) {
            this.tcs.updateSingleLock(this.tcs.currentUnit.parent, 'time', true);
          }
          return this.tcs.setUnitNavigationRequest(
            UnitNavigationTarget.NEXT ?? UnitNavigationTarget.END,
            true
          );
        }
        return true;
      case MaxTimerEvent.CANCELLED:
        if (this.tcs.shouldShowConfirmationUI()) {
          this.snackBar.open(this.cts.getCustomText('booklet_msgTimerCancelled'), '', {
            duration: 5000,
            panelClass: ['snackbar-time-canceled']
          });
        }
        this.tcs.timers[timer.id] = 0;
        // attention: TODO store timer as well in localStorage to prevent F5-cheating
        this.tcs.addToTestStateBuffer('TESTLETS_TIMELEFT', JSON.stringify(this.tcs.timers));
        this.timerValue = null;
        if (this.tcs.testMode.forceTimeRestrictions && this.tcs.currentUnit) {
          this.tcs.updateSingleLock(this.tcs.currentUnit.parent, 'time', true);
        }
        return true;
      case MaxTimerEvent.INTERRUPTED:
        this.timerValue = null;
        return true;
      case MaxTimerEvent.STEP:
        this.timerValue = timer;
        this.tcs.timers[timer.id] = timer.timeLeftSeconds / 60;
        if ((timer.timeLeftSeconds % 15) === 0) {
          // attention: TODO store timer as well in localStorage to prevent F5-cheating
          this.tcs.addToTestStateBuffer('TESTLETS_TIMELEFT', JSON.stringify(this.tcs.timers));
        }
        if (this.tcs.timerWarningPoints.includes(minute) && this.tcs.shouldShowConfirmationUI()) {
          const text = this.cts.getCustomText('booklet_msgSoonTimeOver').replace('%s', minute.toString(10));
          this.snackBar.open(text, '', {
            duration: 5000,
            panelClass: ['snackbar-timerWarning']
          });
        }
        return true;
      default:
        return true;
    }
  }

  ngOnDestroy(): void {
    Object.keys(this.subscriptions)
      .filter(subscriptionKey => this.subscriptions[subscriptionKey])
      .forEach(subscriptionKey => {
        this.subscriptions[subscriptionKey]?.unsubscribe();
        this.subscriptions[subscriptionKey] = null;
      });
    if (this.mainDataService.isFullScreen) {
      document.exitFullscreen();
    }
    this.headerService.isHeaderHidden = false;
  }

  @HostListener('window:unload', ['$event'])
  unloadHandler(): void {
    if (!this.tcs.testMode.saveResponses) {
      return;
    }
    if (this.cmd.connectionStatus$.getValue() !== 'ws-online') {
      this.bs.notifyDyingTest(this.tcs.testId);
    }
  }

  async setFullScreen(): Promise<void> {
    if (this.mainDataService.isFullScreen) {
      return;
    }
    const rootElem = document.documentElement;
    if (!rootElem) {
      return;
    }
    if ('requestFullscreen' in rootElem) {
      await rootElem.requestFullscreen();
      return;
    }
    if ('webkitRequestFullscreen' in rootElem) { // iOS
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      await rootElem.webkitRequestFullscreen();
    }
  }

  async toggleFullScreen(): Promise<void> {
    if (this.mainDataService.isFullScreen) {
      await document.exitFullscreen();
    } else {
      await this.setFullScreen();
    }
  }

  async requestFullScreen(): Promise<void> {
    if (this.mainDataService.isFullScreen) {
      return;
    }

    this.messageService.showConfirmDialog({
      title: 'Vollbild',
      content: this.cts.getCustomText('booklet_requestFullscreen'),
      confirmText: 'Ja',
      cancelText: 'Nein'
    }).subscribe(async (confirmed: boolean) => {
      if (confirmed) await this.setFullScreen();
    });
  }

  gotoNextPage(): void {
    if (this.pageService.isLastPage()) {
      if (this.tcs.shouldShowConfirmationUI()) this.messageService.showSnackbar('Bereits auf der letzten Seite');
      return;
    }
    this.gotoPage(this.pageService.currentPageIndex += 1);
  }

  gotoPreviousPage(): void {
    if (this.pageService.isFirstPage()) {
      if (this.tcs.shouldShowConfirmationUI()) this.messageService.showSnackbar('Bereits auf der ersten Seite');
      return;
    }
    this.gotoPage(this.pageService.currentPageIndex -= 1);
  }

  gotoPage(targetPageIndex: number): void {
    this.pageService.setCurrentPage(targetPageIndex);
    this.apiService.sendPageNav(this.tcs.currentUnit?.alias,
      this.pageService.pages[this.pageService.currentPageIndex].id);
  }

  protected readonly unitNavigationTarget = UnitNavigationTarget;

  protected showGlobalBack = false;
  protected deriveGlobalBack(): boolean {
    const mode = this.tcs.booklet?.config.navbar_backward_button;

    switch (mode) {
      case 'DYNAMIC':
      case 'UNITS':
      case 'PAGES':
        return true;
      case 'HIDDEN':
      case undefined:
      default:
        return false;
    }
  }

  protected showGlobalForward: boolean = false;
  protected deriveGlobalForward(): boolean {
    const mode = this.tcs.booklet?.config.navbar_forward_button;

    switch (mode) {
      case 'DYNAMIC':
      case 'UNITS':
      case 'PAGES':
        return true;
      case 'HIDDEN':
      case undefined:
      default:
        return false;
    }
  }

  protected onNavBack() {
    const mode = this.tcs.booklet?.config?.navbar_backward_button;
    if (mode === 'UNITS' || (mode === 'DYNAMIC' && this.pageService.isFirstPage())) {
      this.tcs.setUnitNavigationRequest(UnitNavigationTarget.PREVIOUS);
    } else {
      this.gotoPreviousPage();
    }
  }

  protected onNavForward() {
    const mode = this.tcs.booklet?.config?.navbar_forward_button;
    if (mode === 'UNITS' || (mode === 'DYNAMIC' && this.pageService.isLastPage())) {
      this.tcs.setUnitNavigationRequest(UnitNavigationTarget.NEXT);
    } else {
      this.gotoNextPage();
    }
  }
}

import {
  Component, ElementRef, OnDestroy, OnInit, ViewChild
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Sort } from '@angular/material/sort';
import { MatSidenav } from '@angular/material/sidenav';
import {
  interval, Observable, of, Subscription
} from 'rxjs';
import { MatDialog } from '@angular/material/dialog';
import { MatSlideToggleChange } from '@angular/material/slide-toggle';
import { MatCheckboxChange } from '@angular/material/checkbox';
import { catchError, switchMap } from 'rxjs/operators';
import { KeyValue } from '@angular/common';
import {
  CustomtextService, ConnectionStatus,
  MainDataService
} from '../shared/shared.module';
import { BackendService } from './backend.service';
import {
  TestViewDisplayOptions,
  TestViewDisplayOptionKey,
  Selected,
  TestSession,
  TestSessionSetStat,
  CommandResponse,
  UIMessage,
  isBooklet,
  TestSessionFilter,
  TestSessionFilterListEntry,
  testSessionFilterListEntrySources, Profile, isColumnOption, isViewOption, isYesNoOption
} from './group-monitor.interfaces';
import { TestSessionManager } from './test-session-manager/test-session-manager.service';
import { BookletUtil } from './booklet/booklet.util';
import { AddFilterDialogComponent } from './components/add-filter-dialog/add-filter-dialog.component';
import {
  TimeRestrictionDialogComponent,
  TimeRestrictionDialogData
} from './time-restriction-dialog/time-restriction-dialog.component';
import { ComponentUtilService } from '../shared/services/component-util.service';
import { HeaderService } from '@shared/services/header.service';
import { MessageService } from '@shared/services/message.service';

@Component({
  selector: 'tc-group-monitor',
  templateUrl: './group-monitor.component.html',
  styleUrls: [
    './group-monitor.component.css'
  ],
  standalone: false
})
export class GroupMonitorComponent implements OnInit, OnDestroy {
  connectionStatus$: Observable<ConnectionStatus> | null = null;

  groupLabel = '';

  currentlySelected: Selected | null = null;
  CurrentlyMarked: Selected | null = null;

  displayOptions: TestViewDisplayOptions = {
    view: 'medium',
    groupColumn: 'hide',
    bookletColumn: 'show',
    blockColumn: 'show',
    unitColumn: 'hide',
    bookletStatesColumns: [],
    highlightSpecies: false,
    manualChecking: false,
    autoselectNextBlock: true
  };

  isScrollable = false;
  isClosing = false;
  checkedSessionCount = 0;

  quickFilter: string = '';
  quickFilterBoxOpen: boolean = false;

  messages: UIMessage[] = [];

  bookletStates: { [p: string]: string } = {};

  private subscriptions: Subscription[] = [];

  @ViewChild('adminbackground') mainElem!: ElementRef;
  @ViewChild('sidenav', { static: true }) sidenav!: MatSidenav;

  constructor(
    public dialog: MatDialog,
    private route: ActivatedRoute,
    private bs: BackendService,
    public tsm: TestSessionManager,
    private router: Router,
    private cts: CustomtextService,
    public mds: MainDataService,
    private addFilterDialog: MatDialog,
    private componentUtilService: ComponentUtilService,
    private headerService: HeaderService,
    private messageService: MessageService
  ) {}

  ngOnInit(): void {
    this.subscriptions = [
      this.route.params.subscribe(params => {
        this.groupLabel = this.mds.getAccessObject('testGroupMonitor', params['group-name']).label;
        const profileId = params['profile-id'];
        if (profileId) {
          this.bs.getProfile(profileId).subscribe(profile => this.applyProfile(profile));
        }
        this.tsm.connect(params['group-name']);
      }),
      this.tsm.sessionsStats$.subscribe(stats => {
        this.onSessionsUpdate(stats);
      }),
      this.tsm.checkedStats$.subscribe(stats => {
        this.onCheckedChange(stats);
      }),
      this.tsm.commandResponses$.subscribe(commandResponse => {
        this.messages.push(this.commandResponseToMessage(commandResponse));
      }),
      this.tsm.commandResponses$
        .pipe(switchMap(() => interval(7000)))
        .subscribe(() => { this.messages.shift(); })
    ];

    this.connectionStatus$ = this.bs.connectionStatus$;
    this.mds.appSubTitle$.next(this.cts.getCustomText('gm_headline') ?? '');
    this.tsm.resetFilters();

    this.headerService.title = `${this.mds.appTitle$.value} ${this.mds.appSubTitle$.value} - ${this.groupLabel}`;
  }

  private commandResponseToMessage(commandResponse: CommandResponse): UIMessage {
    const command = this.cts.getCustomText(`gm_control_${commandResponse.commandType}`) || commandResponse.commandType;
    const successWarning = this.cts.getCustomText(`gm_control_${commandResponse.commandType}_success_warning`) || '';
    if (!commandResponse.testIds.length) {
      return {
        level: 'warning',
        text: 'Keine Tests Betroffen von: `%s`',
        customtext: 'gm_message_no_session_affected_by_command',
        replacements: [command, commandResponse.testIds.length.toString(10)]
      };
    }
    return {
      level: successWarning ? 'warning' : 'info',
      text: '`%s` an `%s` tests gesendet! %s',
      customtext: 'gm_message_command_sent_n_sessions',
      replacements: [command, commandResponse.testIds.length.toString(10), successWarning]
    };
  }

  ngOnDestroy(): void {
    this.tsm.disconnect();
    this.subscriptions.forEach(subscription => subscription.unsubscribe());
  }

  ngAfterViewChecked(): void {
    this.isScrollable = this.mainElem.nativeElement.clientHeight < this.mainElem.nativeElement.scrollHeight;
  }

  private onSessionsUpdate(stats: TestSessionSetStat): void {
    this.displayOptions.highlightSpecies = (stats.differentBookletSpecies > 1);

    if (!this.tsm.checkingOptions.enableAutoCheckAll) {
      this.displayOptions.manualChecking = true;
    }

    this.bookletStates = stats.bookletStateLabels;
  }

  private onCheckedChange(stats: TestSessionSetStat): void {
    // the test commands act on the checked sessions, so the toolbar disables them when there are none
    this.checkedSessionCount = stats.numberOfSessions;

    if (stats.differentBookletSpecies > 1) {
      this.currentlySelected = null;
    }
  }

  // eslint-disable-next-line class-methods-use-this
  trackSession = (index: number, session: TestSession): number => session.data.testId;

  setTableSorting(sort: Sort): void {
    if (!sort.active || sort.direction === '') {
      return;
    }
    this.tsm.sortBy$?.next(sort);
  }

  setDisplayOption(option: TestViewDisplayOptionKey, value: TestViewDisplayOptions[TestViewDisplayOptionKey]): void {
    if (Object.keys(this.displayOptions).includes(option)) {
      (this.displayOptions as {
        [option in TestViewDisplayOptionKey]: TestViewDisplayOptions[TestViewDisplayOptionKey]
      })[option] = value;
    }
  }

  toggleBookletStatesColumn(column: string): void {
    this.displayOptions.bookletStatesColumns =
      (this.displayOptions.bookletStatesColumns.includes(column)) ?
        this.displayOptions.bookletStatesColumns.filter(c => c !== column) :
        [...this.displayOptions.bookletStatesColumns, column].sort();
  }

  scrollDown(): void {
    this.mainElem.nativeElement.scrollTo(0, this.mainElem.nativeElement.scrollHeight);
  }

  updateScrollHint(): void {
    const elem = this.mainElem.nativeElement;
    const reachedBottom = (elem.scrollTop + elem.clientHeight === elem.scrollHeight);
    elem.classList[reachedBottom ? 'add' : 'remove']('hide-scroll-hint');
  }

  getSessionColor(session: TestSession): string {
    const stripes = (c1: string, c2: string) => `repeating-linear-gradient(45deg, ${c1}, ${c1} 10px, ${c2} 10px, ${c2} 20px)`;
    const hsl = (h: number, s: number, l: number) => `hsl(${h}, ${s}%, ${l}%)`;
    const colorful = this.displayOptions.highlightSpecies && session.booklet.species;
    const h = colorful ? (
      session.booklet.species.length *
      session.booklet.species.charCodeAt(0) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 2) *
      session.booklet.species.charCodeAt(3 * (session.booklet.species.length / 4)) *
      session.booklet.species.charCodeAt(session.booklet.species.length - 1)
    ) % 360 : 0;

    switch (session.state) {
      case 'paused':
        return hsl(h, colorful ? 45 : 0, 90);
      case 'pending':
      case 'locked':
        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 0, 92));
      case 'error':
        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 30, 95));
      default:
        return hsl(h, colorful ? 75 : 0, colorful ? 95 : 100);
    }
  }

  markElement(marking: Selected): void {
    this.CurrentlyMarked = marking;
  }

  selectElement(selected: Selected): void {
    this.tsm.checkSessionsBySelection(selected);
    this.currentlySelected = selected;
  }

  finishEverythingCommand(): void {
    this.messageService.showConfirmDialog({
      title: 'Testdurchführung beenden',
      content: 'Achtung! Diese Aktion sperrt und beendet sämtliche Tests dieser Sitzung.',
      confirmText: 'Ja, ich möchte die Testdurchführung beenden'
    }).subscribe((confirmed: boolean) => {
      if (confirmed) {
        this.isClosing = true;
        this.tsm.commandFinishEverything()
          .pipe(catchError(err => {
            this.isClosing = false;
            throw err;
          }))
          .subscribe(() => {
            setTimeout(() => { this.router.navigateByUrl('/r/starter'); }, 2000);
          });
      }
    });
  }

  testCommandGoto(): void {
    if (!this.currentlySelected?.element?.blockId) {
      this.messages.push({
        level: 'warning',
        customtext: 'gm_test_command_no_selected_block',
        text: 'Kein Zielblock ausgewählt'
      });
      return;
    }

    (this.tsm.checked
      .some(testSession => isBooklet(testSession.booklet) &&
          this.currentlySelected?.element &&
          testSession.timeLeft &&
          (testSession.timeLeft[this.currentlySelected?.element?.id] <= 0)
      ) ?
      this.dialog.open(
        TimeRestrictionDialogComponent, {
          width: 'auto',
          data: <TimeRestrictionDialogData>{
            title:
                this.cts.getCustomText('gm_control_goto_unlock_blocks_confirm_headline'),
            content:
                this.cts.getCustomText('gm_control_goto_unlock_blocks_confirm_text'),
            confirmbuttonlabel: 'OK',
            showcancel: true,
            remainingTime: this.tsm.getMaxTimeAcrossAllSessions(this.currentlySelected)
          }
        }
      ).afterClosed() :
      of(1) // 1 as in 'true'
    )
      .subscribe((confirmed?: number | boolean) => {
        if (!confirmed || confirmed === 0 || !this.currentlySelected) return;
        const newTimeLeft = confirmed as number;
        this.tsm.testCommandGoto(this.currentlySelected, newTimeLeft)
          .subscribe(() => this.selectNextBlock());
      });
  }

  private selectNextBlock(): void {
    if (!this.displayOptions.autoselectNextBlock) return;
    if (!this.currentlySelected) return;
    if (!isBooklet(this.currentlySelected.originSession.booklet)) return;
    this.currentlySelected = {
      element: this.currentlySelected.element?.nextBlockId ?
        BookletUtil.getBlockById(
          this.currentlySelected.element.nextBlockId,
          this.currentlySelected.originSession.booklet
        ) : null,
      inversion: false,
      originSession: this.currentlySelected.originSession,
      nthClick: this.currentlySelected.nthClick
    };
  }

  unlockCommand(): void {
    this.tsm.testCommandUnlock();
  }

  toggleChecked(session: TestSession): void {
    if (!this.tsm.isChecked(session)) {
      this.tsm.checkSession(session);
    } else {
      if (session.data.testId === this.currentlySelected?.originSession?.data?.testId) {
        this.currentlySelected = null;
      }
      this.tsm.uncheckSession(session);
    }
  }

  invertChecked(event: Event): boolean {
    event.preventDefault();
    this.tsm.invertChecked();
    return false;
  }

  toggleAlwaysCheckAll(event: MatSlideToggleChange): void {
    if (this.tsm.checkingOptions.enableAutoCheckAll && event.checked) {
      // TODO not ideal - try to reset the state properly, instead of reloading the component
      this.componentUtilService.reloadComponent(true);
    } else {
      this.tsm.checkNone();
      this.displayOptions.manualChecking = true;
      this.tsm.checkingOptions.autoCheckAll = false;
      this.currentlySelected = null;
    }
  }

  toggleCheckAll(event: MatCheckboxChange): void {
    if (event.checked) {
      this.tsm.checkAll();
    } else {
      this.tsm.checkNone();
      this.currentlySelected = null;
    }
  }

  addFilter(): void {
    this.openFilterDialog();
  }

  editFilter(key: string): void {
    this.openFilterDialog(this.tsm.filterOptions[key]);
  }

  private openFilterDialog(filterEntry: TestSessionFilterListEntry | undefined = undefined) {
    const data = filterEntry ? filterEntry.filter : {};
    const dialogRef = this.addFilterDialog.open(AddFilterDialogComponent, { width: 'auto', data });

    dialogRef.afterClosed().subscribe((newFilter: TestSessionFilter) => {
      if (!newFilter) return;
      this.tsm.filterOptions[newFilter.id] = {
        selected: true,
        filter: newFilter,
        source: filterEntry?.source || 'custom'
      };
      this.tsm.refreshFilters();
    });
  }

  // eslint-disable-next-line class-methods-use-this
  sortFilterMenuEntries(
    a: KeyValue<string, TestSessionFilterListEntry>,
    b: KeyValue<string, TestSessionFilterListEntry>
  ): number {
    const aLevel = testSessionFilterListEntrySources.indexOf(a.value.source);
    const bLevel = testSessionFilterListEntrySources.indexOf(b.value.source);
    if (aLevel !== bLevel) return aLevel - bLevel;
    return a.value.filter.label > b.value.filter.label ? 1 : -1;
  }

  quickFilterOnUpdateModel() {
    if (!this.quickFilter) {
      this.tsm.filterOptions.quick.selected = false;
    } else {
      this.tsm.filterOptions.quick.selected = true;
      this.tsm.filterOptions.quick.filter.value = this.quickFilter;
    }

    this.tsm.refreshFilters();
  }

  toggleQuickFilterBox(): void {
    this.quickFilterBoxOpen = !this.quickFilterBoxOpen;
  }

  quickFilterOnFocusOut(): void {
    if (!this.quickFilter) this.quickFilterBoxOpen = false;
  }

  private applyProfile(p: Profile): void {
    if (isColumnOption(p.settings.blockColumn)) this.displayOptions.blockColumn = p.settings.blockColumn;
    if (isColumnOption(p.settings.unitColumn)) this.displayOptions.unitColumn = p.settings.unitColumn;
    if (isColumnOption(p.settings.groupColumn)) this.displayOptions.groupColumn = p.settings.groupColumn;
    if (isColumnOption(p.settings.bookletColumn)) this.displayOptions.bookletColumn = p.settings.bookletColumn;
    if (isViewOption(p.settings.view)) this.displayOptions.view = p.settings.view;
    if (isYesNoOption(p.settings.autoselectNextBlock)) this.displayOptions.autoselectNextBlock = p.settings.autoselectNextBlock !== 'no';

    (p.filters || [])
      .forEach((filter: TestSessionFilter, index: number) => {
        filter.id = `profile_filter:${index}`;
        this.tsm.filterOptions[filter.id] = { selected: true, filter, source: 'profile' };
      });

    this.displayOptions.bookletStatesColumns = (p.settings.bookletStatesColumns || '').split(/[\W,]+/);

    Object.entries(p.filtersEnabled || [])
      .forEach(([f, onOff]) => {
        if (this.tsm.filterOptions[f]) {
          this.tsm.filterOptions[f].selected = ['1', 'true', 'on', 'yes'].includes(onOff);
        }
      });
    this.tsm.refreshFilters();
  }
}

import { TestSessionChange } from 'testcenter-common/interfaces/test-session-change.interface';
import {
  BookletDef, BookletStateDef, BookletStateOptionDef, TestletDef, UnitDef
} from '../shared/shared.module';

export interface GroupMonitorConfig {
  checkForIdleInterval: number;
}

export type TestSessionData = Readonly<TestSessionChange>;

export interface TestSession {
  readonly data: TestSessionData;
  readonly state: TestSessionSuperState;
  readonly current: UnitContext | null;
  readonly booklet: Booklet | BookletError;
  readonly clearedCodes: string[] | null;
  readonly timeLeft: Record<string, number> | null;
  readonly bookletStates: { [state: string]: string } | null;
}

export const TestSessionsSuperStates = ['monitor_group', 'demo', 'pending', 'locked', 'error',
  'controller_terminated', 'connection_lost', 'paused', 'focus_lost', 'idle',
  'connection_websocket', 'connection_polling', 'ok'] as const;
export type TestSessionSuperState = typeof TestSessionsSuperStates[number];

export type TestViewDisplayOptionKey = keyof TestViewDisplayOptions;

// analogous to GroupMonitorProfileFilterField in Testtakers.xsd
export const testSessionFilterTargetLists = {
  advanced: [
    'groupName',
    'bookletId',
    'blockId',
    'testState',
    'mode',
    'bookletSpecies',
    'unitId'
  ],
  basic: [
    'bookletLabel',
    'personLabel',
    'state',
    'blockLabel',
    'unitLabel',
    'bookletStates'
  ]
} as const;

export const testSessionFilterTargets = [
  ...testSessionFilterTargetLists.basic,
  ...testSessionFilterTargetLists.advanced
] as const;

export const testSessionFilterTypeLists = {
  basic: ['substring', 'equal'],
  advanced: ['regex']
} as const;

export const testSessionFilterTypes = [
  ...testSessionFilterTypeLists.basic,
  ...testSessionFilterTypeLists.advanced
] as const;

export type TestSessionFilterType = (typeof testSessionFilterTypes)[number];

export type TestSessionFilterTarget = (typeof testSessionFilterTargets)[number];

export interface TestSessionFilter {
  target: TestSessionFilterTarget;
  value: string | string[];
  id: string;
  label: string;
  subValue?: string;
  type: TestSessionFilterType;
  not: boolean;
}

export const isTestSessionFilter = (obj: object): obj is TestSessionFilter => ('target' in obj) &&
  ('value' in obj) && ('id' in obj) && ('label' in obj) && ('type' in obj) && ('not' in obj) &&
  (typeof obj.type === 'string') && (typeof obj.target === 'string') &&
  (typeof obj.label === 'string') && (typeof obj.not === 'boolean') &&
  (testSessionFilterTypes as readonly string[]).includes(obj.type) &&
  (testSessionFilterTargets as readonly string[]).includes(obj.target);

export const isAdvancedTestSessionFilterTarget =
  (target: TestSessionFilterTarget): boolean => (testSessionFilterTargetLists.advanced)
    .some(t => t === target);

export const isAdvancedTestSessionFilterType =
  (type: TestSessionFilterType): boolean => testSessionFilterTypeLists.advanced
    .some(t => t === type);

export interface MonitorProfileTestViewDisplayOptions {
  blockColumn: ColumnOption;
  unitColumn: ColumnOption;
  view: ViewOption;
  groupColumn: ColumnOption;
  bookletColumn: ColumnOption;
  bookletStatesColumns: string[];
  autoselectNextBlock: boolean;
}

export type ColumnOption = 'show' | 'hide';
export type ViewOption = 'full' | 'medium' | 'small';
export type YesNoOption = 'yes' | 'no';

export const isColumnOption = (v: string): v is ColumnOption => ['show', 'hide'].includes(v);
export const isViewOption = (v: string): v is ViewOption => ['full', 'medium', 'small'].includes(v);
export const isYesNoOption = (v: string): v is YesNoOption => ['yes', 'no'].includes(v);

export interface TestViewDisplayOptions extends MonitorProfileTestViewDisplayOptions {
  highlightSpecies: boolean;
  manualChecking: boolean;
}

export interface Profile {
  id: string;
  label: string;
  settings: { [key: string]: string };
  filtersEnabled: { [key: string]: string };
  filters: TestSessionFilter[];
}

export const testSessionFilterListEntrySources = ['base', 'quick', 'profile', 'custom'] as const;

export type TestSessionFilterListEntrySource = typeof testSessionFilterListEntrySources[number];

export interface TestSessionFilterListEntry {
  filter: TestSessionFilter,
  selected: boolean,
  source: TestSessionFilterListEntrySource
}

export interface TestSessionFilterList {
  [filterId: string]: TestSessionFilterListEntry
}

export interface CheckingOptions {
  enableAutoCheckAll: boolean;
  autoCheckAll: boolean;
}

export interface UnitContext {
  unit: UnitDef | undefined;
  parent: Testlet;
  ancestor: Testlet;
  indexGlobal: number;
  indexLocal: number;
  indexAncestor: number;
}

export interface Selected {
  element: Testlet | null;
  originSession: TestSession;
  nthClick: 'first' | 'second' | 'third';
  inversion: boolean;
}

export interface TestSessionSetStat {
  allChecked: boolean;
  numberOfSessions: number;
  differentBooklets: number;
  differentBookletSpecies: number;
  pausedSessions: number;
  lockedSessions: number;
  bookletStateLabels: { [bookletStateId: string]: string };
}

export interface UIMessage {
  level: 'error' | 'warning' | 'info' | 'success';
  text: string;
  customtext: string;
  replacements?: string[]
}

export interface CommandResponse {
  commandType: string;
  testIds: number[];
}

export interface GotoCommandData {
  [firstUnitId: string]: CommandParameter;
}

interface CommandParameter {
  ids: number[];
  isClosed?: boolean;
}

export type Unit = UnitDef;

export interface Booklet extends BookletDef<Testlet, BookletState> {
  species: string;
}

export interface Testlet extends TestletDef<Testlet, Unit> {
  descendantCount: number;
  blockId?: string;
  nextBlockId?: string;
}

export type BookletStateOption = BookletStateOptionDef;

export interface BookletState extends BookletStateDef<BookletStateOption> {
  default: string;
}

export function isUnit(testletOrUnit: Testlet | UnitDef): testletOrUnit is UnitDef {
  return !('children' in testletOrUnit);
}

export function isTestlet(testletOrUnit: Testlet | UnitDef): testletOrUnit is Testlet {
  return !isUnit(testletOrUnit);
}

export function isBooklet(bookletOrError: Booklet | BookletError): bookletOrError is Booklet {
  return bookletOrError && !('error' in bookletOrError);
}

export interface BookletError {
  error: 'xml' | 'missing-id' | 'missing-file' | 'general';
  species: null;
}

export type TestSessionFilterSubValueSelect = BookletStateDef<BookletStateOption>;

import {
  Component, Inject, OnInit
} from '@angular/core';
import { MAT_DIALOG_DATA } from '@angular/material/dialog';
import {
  isBooklet,
  TestSessionFilter,
  TestSessionFilterTarget,
  testSessionFilterTargets,
  testSessionFilterTargetLists,
  testSessionFilterTypeLists,
  testSessionFilterTypes,
  isTestSessionFilter,
  isAdvancedTestSessionFilterTarget,
  isAdvancedTestSessionFilterType,
  TestSessionFilterSubValueSelect
} from '../../group-monitor.interfaces';
import { superStates } from '../../test-session/super-states';
import { CustomtextService, TestMode } from '../../../shared/shared.module';
import { TestSessionManager } from '../../test-session-manager/test-session-manager.service';

@Component({
  templateUrl: './add-filter-dialog.component.html',
  styleUrls: [
    'add-filter-dialog.component.css'
  ],
  standalone: false
})
export class AddFilterDialogComponent implements OnInit {
  constructor(
    public tsm: TestSessionManager,
    private cts: CustomtextService,
    @Inject(MAT_DIALOG_DATA) data: TestSessionFilter
  ) {
    if (data && isTestSessionFilter(data)) {
      this.originalId = data.id;
      this.filter = data;
    }
  }

  filter: TestSessionFilter = {
    id: '',
    label: '',
    target: 'personLabel',
    value: '',
    not: false,
    type: 'equal'
  };

  readonly targets = {
    basic: testSessionFilterTargetLists.basic,
    all: testSessionFilterTargets
  };

  readonly filterTypes = {
    basic: testSessionFilterTypeLists.basic,
    all: testSessionFilterTypes
  };

  readonly superStates = superStates;

  readonly lists: { [key in TestSessionFilterTarget]: string[] } = {
    blockId: [],
    blockLabel: [],
    bookletLabel: [],
    bookletId: [],
    bookletSpecies: [],
    groupName: [],
    mode: [],
    personLabel: [],
    state: [],
    testState: [],
    unitLabel: [],
    unitId: [],
    bookletStates: []
  };

  readonly subValueLists:
  Partial<{ [field in TestSessionFilterTarget] : { [value: string] : TestSessionFilterSubValueSelect } }> =
      { bookletStates: {} };

  isValid: boolean = true;
  advancedMode: boolean = false;
  originalId: string | undefined;

  ngOnInit(): void {
    const pushUnique = <T>(arr: T[], item: T): void => {
      if (item && !arr.includes(item)) arr.push(item);
    };
    this.tsm.sessions
      .forEach(session => {
        pushUnique(this.lists.groupName, session.data.groupName);
        pushUnique(this.lists.bookletId, session.data.bookletName || '');
        pushUnique(this.lists.blockId, session.current?.ancestor?.blockId || '');
        pushUnique(this.lists.blockLabel, session.current?.ancestor?.blockId || '');
        pushUnique(this.lists.bookletSpecies, session.booklet.species || '');
        pushUnique(this.lists.unitId, session.current?.unit?.id || '');
        pushUnique(this.lists.unitLabel, session.current?.unit?.label || '');
        if (!isBooklet(session.booklet)) return;
        pushUnique(this.lists.bookletLabel, session.booklet.metadata.label);
        Object.entries(session.booklet.states)
          .forEach(([stateId, state]) => {
            pushUnique(this.lists.bookletStates, stateId);
            if (!this.subValueLists.bookletStates) return;
            this.subValueLists.bookletStates[stateId] = {
              id: stateId,
              label: state.label, //!
              options: { ...state.options }
            };
          });
      });

    this.lists.mode = Object.keys(TestMode.modes).map(mode => mode.toLowerCase());
  }

  validate(): void {
    this.isValid = true;
    if (typeof this.filter.value !== 'string') {
      this.isValid = false;
      return;
    }
    if (this.filter.type === 'regex') {
      try {
        // eslint-disable-next-line no-new
        new RegExp(this.filter.value);
      } catch (e) {
        this.isValid = false;
      }
    }
  }

  updateFilterId(): void {
    if (['state'].includes(this.filter.target) && !this.isStringArray(this.filter.value)) {
      this.filter.value = [];
    }
    if (!['bookletStates', 'testState'].includes(this.filter.target)) {
      this.filter.subValue = undefined;
    }
    const newId = [
      this.filter.target,
      this.filter.not ? 'not_' : '',
      this.filter.type,
      ...(this.isStringArray(this.filter.value) ? this.filter.value : [this.filter.value]),
      this.filter.subValue
    ]
      .filter(t => !!t)
      .join('_');
    this.filter.id = this.originalId || newId;

    const label = {
      target: this.cts.getCustomText(`gm_filter_target_${this.filter.target}`) || this.filter.target,
      type: this.cts.getCustomText(`gm_filter_type_${this.filter.type}`) || this.filter.type,
      not: this.filter.not ? (this.cts.getCustomText('gm_filter_not') ?? 'not') : '',
      value: '',
      subValue: ''
    };
    if (this.isStringArray(this.filter.value)) {
      label.value = this.filter.value.join(', ');
    } else if (this.filter.subValue) {
      label.value = this.subValueLists?.[this.filter.target]?.[this.filter.value]?.label || this.filter.value;
      label.subValue =
        this.subValueLists?.[this.filter.target]?.[this.filter.value]?.options[this.filter.subValue]?.label ||
          this.filter.subValue;
    } else {
      label.value = this.filter.value;
    }
    this.filter.label = (
      this.filter.subValue ?
        [label.target, label.value, label.type, label.not, label.subValue] :
        [label.target, label.type, label.not, label.value]
    )
      .filter(a => !!a)
      .join(' ');
  }

  protected readonly isAdvancedTestSessionFilterTarget = isAdvancedTestSessionFilterTarget;
  protected readonly isAdvancedTestSessionFilterType = isAdvancedTestSessionFilterType;

  // eslint-disable-next-line class-methods-use-this
  protected readonly isStringArray = (s : string | string[]): s is string[] => Array.isArray(s);
}
